window.loadQuizzes("T01_Alternator", [{"q": "What is the purpose of the AVR in an alternator?", "a": "Automatically maintains constant output voltage by controlling excitation current", "opts": ["Controls frequency", "Maintains constant voltage", "Controls speed", "Monitors earth faults"], "exp": "AVR = Automatic Voltage Regulator. It senses terminal voltage and adjusts field current to keep voltage constant under varying loads.", "id": "T01_Alternator_Q001", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "In a brushless alternator, the rotating rectifiers are mounted on:", "a": "The rotor shaft", "opts": ["Stator frame", "Rotor shaft", "Exciter stator", "Control panel"], "exp": "Rotating rectifiers (diodes) are on the rotor shaft, converting AC from exciter to DC for the main field winding \u2014 no brushes needed.", "id": "T01_Alternator_Q002", "topic": "T01_Alternator", "cat": "BL"}, {"q": "Why is a brushless alternator preferred in marine applications?", "a": "No brush/slip ring maintenance, no sparking, suitable for humid environments", "opts": ["Higher output voltage", "No maintenance at all", "No brush/slip ring maintenance, no sparking, suitable for humid environments", "Lower weight"], "exp": "No carbon brush dust, no sparking in hazardous areas, suitable for UMS (unattended machinery spaces).", "id": "T01_Alternator_Q003", "topic": "T01_Alternator", "cat": "BL"}, {"q": "What does 'droop' refer to in parallel generator operation?", "a": "Deliberate slight speed reduction with increasing load for stable load sharing", "opts": ["Voltage drop under fault", "Speed reduction at no load", "Deliberate slight speed reduction with increasing load for stable load sharing", "Frequency fluctuation"], "exp": "Droop characteristic allows governors to share load automatically. Without droop, two generators on bus would 'hunt' \u2014 fighting each other for load.", "id": "T01_Alternator_Q004", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Before synchronising a generator, which conditions must be met?", "a": "Voltage, frequency, phase sequence and phase angle must match", "opts": ["Only voltage and frequency", "Voltage and phase sequence only", "Voltage, frequency, phase sequence and phase angle must match", "Only phase sequence"], "exp": "All four conditions: same voltage magnitude, same frequency, same phase sequence, and same phase angle (confirmed by synchroscope at 12 o'clock position moving slowly clockwise).", "id": "T01_Alternator_Q005", "topic": "T01_Alternator", "cat": "SY"}, {"q": "What happens if a generator is closed onto busbar with wrong phase sequence?", "a": "Violent mechanical shock, possible winding damage, catastrophic failure", "opts": ["Slight voltage dip only", "Gentle synchronisation", "Violent mechanical shock, possible winding damage, catastrophic failure", "Automatic protection trips instantly with no damage"], "exp": "Phase sequence reversal causes the machine to act as a brake against itself \u2014 enormous current surge and mechanical stress.", "id": "T01_Alternator_Q006", "topic": "T01_Alternator", "cat": "SY"}, {"q": "What is the function of a synchroscope?", "a": "Indicates phase difference and relative speed between incoming and running generator", "opts": ["Measures power factor", "Indicates phase difference and relative speed between incoming and running generator", "Measures insulation resistance", "Controls AVR"], "exp": "Pointer rotating clockwise = incoming is fast (slightly). Pointer at 12 o'clock = in phase. Close breaker just before 12 o'clock while rotating slowly clockwise.", "id": "T01_Alternator_Q007", "topic": "T01_Alternator", "cat": "SY"}, {"q": "Air gap in a marine alternator is typically:", "a": "2\u20134 mm", "opts": ["0.1\u20130.5 mm", "2\u20134 mm", "10\u201315 mm", "50 mm"], "exp": "Typical air gap is 2\u20134 mm. Uneven air gap causes vibration, noise, unbalanced magnetic pull and affects output waveform.", "id": "T01_Alternator_Q008", "topic": "T01_Alternator", "cat": "AG"}, {"q": "How is the air gap of an alternator measured?", "a": "Using feeler gauges at multiple points around the circumference", "opts": ["Using a micrometer", "Using feeler gauges at multiple points around the circumference", "Using a dial gauge", "Estimated by visual inspection"], "exp": "Feeler gauges inserted between rotor and stator at 4\u20138 positions. Values should be within \u00b110% of each other.", "id": "T01_Alternator_Q009", "topic": "T01_Alternator", "cat": "AG"}, {"q": "An open-circuited rotating diode in a brushless alternator causes:", "a": "Reduced output voltage and increased ripple/vibration", "opts": ["Complete loss of excitation", "Reduced output voltage and increased ripple/vibration", "No effect \u2014 other diodes compensate", "Overcurrent trip"], "exp": "One diode failing open means only part of the AC cycle is rectified \u2014 unbalanced DC to field, causing voltage reduction and vibration.", "id": "T01_Alternator_Q010", "topic": "T01_Alternator", "cat": "BL"}, {"q": "A short-circuited rotating diode causes:", "a": "Heavy field current, high voltage output, possible AVR instability", "opts": ["No voltage output", "Reduced voltage", "Heavy field current, high voltage output, possible AVR instability", "Earth fault alarm"], "exp": "Shorted diode short-circuits part of field circuit \u2014 current circulates, causing overheating, high excitation, and hunting.", "id": "T01_Alternator_Q011", "topic": "T01_Alternator", "cat": "BL"}, {"q": "What is the purpose of the reverse power relay?", "a": "Trips the generator breaker if the machine starts motoring (taking power from busbar)", "opts": ["Prevents overvoltage", "Trips the generator breaker if the machine starts motoring (taking power from busbar)", "Prevents overfrequency", "Trips on earth fault"], "exp": "If prime mover fails with breaker closed, alternator would run as synchronous motor \u2014 consuming power. Reverse power relay detects this and opens breaker.", "id": "T01_Alternator_Q012", "topic": "T01_Alternator", "cat": "PR"}, {"q": "What is 'preferential trip' / 'dead ship protection'?", "a": "Sequential shedding of non-essential loads when generator is overloaded, to maintain essential services", "opts": ["Trips all loads simultaneously", "Sequential shedding of non-essential loads when generator is overloaded, to maintain essential services", "Trips the generator itself", "Starts standby generator"], "exp": "Loads shed in pre-set sequence (non-essential first) to prevent generator overload trip. Essential services (steering, fire pump, navigation) preserved.", "id": "T01_Alternator_Q013", "topic": "T01_Alternator", "cat": "PR"}, {"q": "What is the typical insulation class of marine alternator windings?", "a": "Class F (155\u00b0C)", "opts": ["Class A (105\u00b0C)", "Class B (130\u00b0C)", "Class F (155\u00b0C)", "Class H (180\u00b0C)"], "exp": "Class F is standard for marine alternators \u2014 allows operation at higher temperatures common in engine rooms.", "id": "T01_Alternator_Q014", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'flashing the field' of an alternator?", "a": "Applying a momentary DC voltage to restore residual magnetism in the field core", "opts": ["Testing insulation with high voltage", "Applying a momentary DC voltage to restore residual magnetism in the field core", "Cleaning the field windings", "Testing AVR response"], "exp": "If residual magnetism is lost, voltage won't build up. Momentary DC (usually from battery) restores residual flux and allows voltage to build.", "id": "T01_Alternator_Q015", "topic": "T01_Alternator", "cat": "RM"}, {"q": "What safeties are typically fitted to a ship's alternator/generator?", "a": "Reverse power, overspeed, overcurrent, earth fault, low oil pressure, high temperature", "opts": ["Only overcurrent and earth fault", "Reverse power, overspeed, overcurrent, earth fault, low oil pressure, high temperature", "Only mechanical safeties", "Only electrical safeties"], "exp": "Both electrical (reverse power, overcurrent, earth fault, undervoltage) and mechanical (overspeed, low lube oil, high coolant temp) protections.", "id": "T01_Alternator_Q016", "topic": "T01_Alternator", "cat": "PR"}, {"q": "Two alternators in parallel \u2014 one has higher KW, other has lower KW. Likely cause?", "a": "Governor settings differ \u2014 one governor allows more fuel than the other", "opts": ["AVR of one is faulty", "Governor settings differ \u2014 one governor allows more fuel than the other", "Different KVA ratings", "Different number of poles"], "exp": "KW (active power) is shared by governor/speed control. Unequal KW = unequal governor droop settings. Adjust governor of the heavily loaded machine.", "id": "T01_Alternator_Q017", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Two alternators in parallel \u2014 one has higher KVAR, other lower. Likely cause?", "a": "AVR settings differ \u2014 one has higher excitation voltage", "opts": ["Governor fault", "AVR settings differ \u2014 one has higher excitation voltage", "Different frequency", "Earth fault"], "exp": "KVAR (reactive power) is shared by excitation/AVR. Unequal KVAR = unequal excitation. Adjust AVR of the over-excited machine.", "id": "T01_Alternator_Q018", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the significance of the KVA rating of a generator?", "a": "Maximum apparent power it can deliver continuously without overheating", "opts": ["Maximum KW it can produce", "Maximum apparent power it can deliver continuously without overheating", "Maximum current only", "Maximum voltage output"], "exp": "KVA = KW/PF. At unity PF, KVA = KW. At low PF, same KVA delivers less KW. Stator current (hence heating) depends on KVA, not KW.", "id": "T01_Alternator_Q019", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Emergency generator SOLAS requirement \u2014 automatic starting must occur within:", "a": "45 seconds for cargo ships, 30 seconds for passenger ships", "opts": ["60 seconds", "45 seconds for cargo ships, 30 seconds for passenger ships", "15 seconds", "10 seconds"], "exp": "SOLAS II-1/43: cargo ships 45 seconds, passenger ships 30 seconds after main power failure.", "id": "T01_Alternator_Q020", "topic": "T01_Alternator", "cat": "SOL"}, {"q": "Emergency generator fuel flash point must be:", "a": "Above 43\u00b0C (SOLAS requirement)", "opts": ["Above 60\u00b0C", "Above 43\u00b0C (SOLAS requirement)", "Any flash point", "Above 100\u00b0C"], "exp": "SOLAS II-1/43.3.2: fuel for emergency generator must have flash point not less than 43\u00b0C. That's why diesel not gasoline \u2014 safety in ER.", "id": "T01_Alternator_Q021", "topic": "T01_Alternator", "cat": "RM"}, {"q": "What is the purpose of the damper winding (amortisseur) in a synchronous machine?", "a": "Dampen oscillations during load changes and assist starting", "opts": ["Increase output voltage", "Dampen oscillations during load changes and assist starting", "Provide excitation", "Cool the rotor"], "exp": "Short-circuited bars in rotor face \u2014 induced currents oppose oscillations (hunting). Also allows synchronous motor to start as induction motor.", "id": "T01_Alternator_Q022", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What reading would you expect from an IR test on a healthy alternator winding?", "a": "Greater than 1 M\u03a9 (and ideally much higher, >100 M\u03a9 for new winding)", "opts": ["Zero ohms", "Greater than 1 M\u03a9 (and ideally much higher, >100 M\u03a9 for new winding)", "Exactly 1 \u03a9", "500 \u03a9"], "exp": "Polarization Index (PI) test: IR at 10 min / IR at 1 min \u2265 2 indicates healthy insulation. Minimum 1 M\u03a9 required before starting.", "id": "T01_Alternator_Q023", "topic": "T01_Alternator", "cat": "MT"}, {"q": "What voltage and frequency is standard for ship's main power supply?", "a": "440V, 60Hz (common) or 440V/380V, 50Hz/60Hz depending on flag", "opts": ["220V, 50Hz", "440V, 60Hz (common) or 440V/380V, 50Hz/60Hz depending on flag", "11kV, 50Hz", "110V, 60Hz"], "exp": "Most merchant ships: 440V, 60Hz. Some European vessels: 380V, 50Hz. Emergency lighting: often 220V single phase. High power ships: 6.6kV or 11kV.", "id": "T01_Alternator_Q024", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of a load-dependent start (LDS) in an automatic power management system?", "a": "Automatically starts standby generator when connected load exceeds a set percentage of running capacity", "opts": ["Starts generator at fixed time intervals", "Automatically starts standby generator when connected load exceeds a set percentage of running capacity", "Trips generator on overload", "Adjusts AVR automatically"], "exp": "LDS prevents overload by bringing on second generator before first becomes overloaded. Typical setting: 70\u201380% of rated KW.", "id": "T01_Alternator_Q025", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is a synchronous motor?", "a": "AC motor that runs exactly at synchronous speed (NS = 120f/P), with no slip", "opts": ["Motor that synchronises with AVR", "AC motor that runs exactly at synchronous speed (NS = 120f/P), with no slip", "Motor running at variable speed", "DC motor with brushes"], "exp": "NS = 120f/P. No slip. Used for constant speed drives and as synchronous capacitor for PF correction.", "id": "T01_Alternator_Q026", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What checks must be done before closing an ACB for synchronisation?", "a": "Voltage match, frequency match, synchroscope at 12 slowly clockwise, phase sequence verified", "opts": ["Only voltage check", "Voltage match, frequency match, synchroscope at 12 slowly clockwise, phase sequence verified", "Only frequency check", "Only phase sequence check"], "exp": "All four synchronising conditions must be met. Phase sequence checked once at installation \u2014 not every time. Voltage, freq and phase angle checked every sync.", "id": "T01_Alternator_Q027", "topic": "T01_Alternator", "cat": "SY"}, {"q": "How do you test the overspeed trip of a diesel generator?", "a": "Gradually increase speed by adjusting governor until overspeed trip activates (typically 115% of rated speed)", "opts": ["Disconnect governor and let engine run freely", "Gradually increase speed by adjusting governor until overspeed trip activates (typically 115% of rated speed)", "Apply load suddenly then remove", "Test only in dry dock"], "exp": "Mechanical overspeed trip typically set at 110\u2013115% of rated speed. Test with generator off-load, gradually increasing speed via governor control. Record test in logbook.", "id": "T01_Alternator_Q028", "topic": "T01_Alternator", "cat": "OS"}, {"q": "What is the Ward Leonard system used for?", "a": "Variable speed DC drive for applications like cranes, winches, and steering gear", "opts": ["AC voltage control", "Variable speed DC drive for applications like cranes, winches, and steering gear", "Generator excitation control", "Motor protection"], "exp": "Generator-motor set: AC motor drives DC generator, DC generator output feeds DC motor. Smooth, wide-range speed control by varying field excitation.", "id": "T01_Alternator_Q029", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Why must alternator AVR be disconnected before megger testing?", "a": "High megger voltage would damage AVR electronic components", "opts": ["To get accurate reading", "High megger voltage would damage AVR electronic components", "To isolate the winding", "AVR is not affected"], "exp": "AVR contains sensitive electronics (transistors, ICs) that cannot withstand the 500V\u20131000V applied during insulation resistance testing.", "id": "T01_Alternator_Q030", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "Nominal speed of a 4-pole alternator on a 60 Hz system is:", "a": "1800 RPM", "opts": ["3600 RPM", "1800 RPM", "1500 RPM", "1200 RPM"], "exp": "NS = 120f/P = 120\u00d760/4 = 1800 RPM. For 50 Hz with 4 poles: NS = 1500 RPM.", "id": "T01_Alternator_Q031", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of the exciter in a brushless alternator?", "a": "Provides AC supply that is rectified to give DC field current for main alternator", "opts": ["Controls output frequency", "Provides AC supply that is rectified to give DC field current for main alternator", "Provides cooling", "Acts as governor"], "exp": "Small AC exciter (stator fixed, rotor rotates) \u2192 rotating diodes rectify \u2192 DC fed to main rotor field \u2192 main alternator produces 3-phase output.", "id": "T01_Alternator_Q032", "topic": "T01_Alternator", "cat": "BL"}, {"q": "Hunting in parallel generators refers to:", "a": "Oscillation of load between generators due to poor governor response", "opts": ["Searching for earth faults", "Oscillation of load between generators due to poor governor response", "Overloading one generator", "Voltage fluctuation"], "exp": "Hunting occurs when governor droop is insufficient or governors have different characteristics. Load swings back and forth between machines.", "id": "T01_Alternator_Q033", "topic": "T01_Alternator", "cat": "LS"}, {"q": "What action if voltage not building up after starting alternator?", "a": "Check residual magnetism, test AVR, check diodes, check exciter winding, check field connections", "opts": ["Increase speed only", "Check residual magnetism, test AVR, check diodes, check exciter winding, check field connections", "Replace the alternator", "Check only the ACB"], "exp": "Systematic approach: check battery exciter supply \u2192 flash field if needed \u2192 test AVR output \u2192 check rotating diodes \u2192 check exciter winding IR \u2192 check main field connections.", "id": "T01_Alternator_Q034", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the PI (Polarisation Index) test?", "a": "Ratio of 10-minute to 1-minute megger reading; PI \u2265 2 indicates good insulation", "opts": ["Peak current test", "Ratio of 10-minute to 1-minute megger reading; PI \u2265 2 indicates good insulation", "Power factor test", "Pressure/insulation test"], "exp": "PI = R10min/R1min. Values: <1 = bad, 1\u20132 = questionable, \u22652 = good, \u22654 = excellent. Indicates moisture/contamination in winding insulation.", "id": "T01_Alternator_Q035", "topic": "T01_Alternator", "cat": "MT"}, {"q": "What is meant by 'cold ironing' or 'shore power connection'?", "a": "Supplying ship's electrical power from shore supply while in port to reduce emissions", "opts": ["Connecting metal earthing strips", "Supplying ship's electrical power from shore supply while in port to reduce emissions", "Testing cold machinery", "Shore-based maintenance"], "exp": "Shore power (cold ironing) allows engines to be shut down in port. Requires careful synchronisation or transfer switching. May need frequency/voltage conversion if shore \u2260 ship standard.", "id": "T01_Alternator_Q036", "topic": "T01_Alternator", "cat": "WP"}, {"q": "An alternator is rated 500 kVA at 0.8 PF. What is its kW rating?", "a": "400 kW", "opts": ["500 kW", "400 kW", "625 kW", "300 kW"], "exp": "kW = kVA \u00d7 PF = 500 \u00d7 0.8 = 400 kW.", "id": "T01_Alternator_Q037", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the effect of increasing excitation on an alternator running in parallel?", "a": "Increases reactive power (kVAR) output and raises PF of that machine", "opts": ["Increases kW output", "Increases reactive power (kVAR) output and raises PF of that machine", "Increases frequency", "Reduces voltage"], "exp": "In parallel operation, excitation controls reactive power sharing. More excitation = more kVAR output = more lagging current supplied to load.", "id": "T01_Alternator_Q038", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the significance of the number of poles in an alternator?", "a": "Determines synchronous speed: NS = 120f/P", "opts": ["Determines voltage", "Determines synchronous speed: NS = 120f/P", "Determines kVA rating", "Determines insulation class"], "exp": "More poles = lower synchronous speed. A slow diesel engine (typically 750 RPM) needs 8 poles for 50 Hz output.", "id": "T01_Alternator_Q039", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Which type of excitation system eliminates all rotating electrical connections?", "a": "Brushless (static exciter with rotating rectifiers)", "opts": ["Slip ring and brush system", "Static exciter only", "Brushless (static exciter with rotating rectifiers)", "Permanent magnet exciter"], "exp": "Brushless system: AC exciter stator (fixed) \u2192 AC exciter rotor (rotates) \u2192 rotating rectifiers \u2192 main field (rotates). Zero rotating electrical contacts.", "id": "T01_Alternator_Q040", "topic": "T01_Alternator", "cat": "EX"}, {"q": "What is meant by 'voltage regulation' of an alternator?", "a": "Percentage change in terminal voltage from no-load to full load: (VNL\u2212VFL)/VFL \u00d7 100", "opts": ["AVR control range", "Percentage change in terminal voltage from no-load to full load: (VNL\u2212VFL)/VFL \u00d7 100", "Voltage drop across winding", "Output voltage stability"], "exp": "Good regulation = small percentage. Marine alternators: typically 3\u20135% regulation with AVR active, could be 20\u201340% without AVR.", "id": "T01_Alternator_Q041", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What does 'blackout' mean in ship's electrical context?", "a": "Complete loss of electrical power to the main switchboard", "opts": ["All lights off", "Complete loss of electrical power to the main switchboard", "Emergency generator fault", "Shore power disconnection"], "exp": "Total blackout: all generators trip. Emergency generator should start automatically within 45 seconds. ETO priorities: restore power, start emergency gen, restore main gen.", "id": "T01_Alternator_Q042", "topic": "T01_Alternator", "cat": "BT"}, {"q": "After a blackout, what is the correct sequence for power restoration?", "a": "Emergency gen starts \u2192 main engine cooling \u2192 start main gen \u2192 synchronise \u2192 restore loads in sequence", "opts": ["Start all generators simultaneously", "Emergency gen starts \u2192 main engine cooling \u2192 start main gen \u2192 synchronise \u2192 restore loads in sequence", "Restore shore power first", "Wait for engineer's order"], "exp": "Systematic restoration prevents overload. Emergency gen provides essential services first. Main gen started, synchronised, then loads restored in priority order.", "id": "T01_Alternator_Q043", "topic": "T01_Alternator", "cat": "BT"}, {"q": "What is the function of the droop resistor in an AVR?", "a": "Causes terminal voltage to droop with increasing reactive current for stable parallel operation", "opts": ["Limits output voltage", "Causes terminal voltage to droop with increasing reactive current for stable parallel operation", "Protects AVR from overcurrent", "Filters voltage ripple"], "exp": "Without reactive droop, two paralleled generators with identical AVRs would have unstable reactive power sharing \u2014 one machine would take all kVAR.", "id": "T01_Alternator_Q044", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "What is shaft generator (shaft driven generator)?", "a": "Generator driven by main propulsion shaft, providing power at variable frequency corrected by frequency converter", "opts": ["Generator on shaft of motor", "Generator driven by main propulsion shaft, providing power at variable frequency corrected by frequency converter", "Emergency generator mounted on propeller shaft", "Auxiliary generator only"], "exp": "Power take-off (PTO) from main engine shaft. Uses frequency converter (cycloconverter or rectifier-inverter) to maintain constant 50/60 Hz output despite varying shaft speed.", "id": "T01_Alternator_Q045", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What maintenance is typically done on a brushless alternator?", "a": "Check diodes, IR test windings, clean, check connections, check air gap, check bearings, test safeties", "opts": ["Only clean externally", "Check diodes, IR test windings, clean, check connections, check air gap, check bearings, test safeties", "Replace bearings only", "Only check AVR"], "exp": "Comprehensive PM: IR test all windings, check/test rotating diodes, check bearing condition (vibration, temperature, noise), clean air passages, verify AVR operation, test all protections.", "id": "T01_Alternator_Q046", "topic": "T01_Alternator", "cat": "BL"}, {"q": "What is the typical test voltage for a megger test on a 440V alternator winding?", "a": "500V DC", "opts": ["240V DC", "500V DC", "1000V DC", "2500V DC"], "exp": "500V megger for 440V equipment is standard. For 11kV equipment: 2500V\u20135000V megger. Rule of thumb: megger voltage \u2248 twice rated voltage + 1000V (min 500V).", "id": "T01_Alternator_Q047", "topic": "T01_Alternator", "cat": "MT"}, {"q": "What is Automatic Mains Failure (AMF)?", "a": "System that automatically starts and connects standby generator when main supply fails", "opts": ["Manual start system", "System that automatically starts and connects standby generator when main supply fails", "AVR backup system", "Load monitoring system"], "exp": "AMF panel monitors bus voltage/frequency. On failure, starts standby gen, waits for it to reach stable output, closes breaker. Typical time: <10 seconds for start + stabilise.", "id": "T01_Alternator_Q048", "topic": "T01_Alternator", "cat": "WP"}, {"q": "Two generators in parallel \u2014 what happens if one governor fails and engine races?", "a": "Overcurrent, reverse power, frequency relay may trip it; mechanical overspeed trip as last resort", "opts": ["Other generator compensates", "Overcurrent, reverse power, frequency relay may trip it; mechanical overspeed trip as last resort", "AVR controls this", "Nothing \u2014 the load sharing is stable"], "exp": "Racing engine causes that generator to take all load \u2192 overcurrent. If it overspeeds, overspeed trip fires. The 'healthy' generator may have breaker open by reverse current from the racing machine.", "id": "T01_Alternator_Q049", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of current transformers (CTs) on the alternator outputs?", "a": "Step down high currents to safe levels for metering and protection relays", "opts": ["Step up voltage for measurement", "Step down high currents to safe levels for metering and protection relays", "Provide earth fault protection directly", "Measure insulation resistance"], "exp": "CTs: typically 5A secondary for standard meters and relays. Never open-circuit a CT secondary when primary is energised \u2014 dangerous overvoltage develops.", "id": "T01_Alternator_Q050", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What does the AVR sense to regulate voltage?", "a": "Terminal voltage of the alternator (and sometimes reactive current for droop)", "opts": ["Speed of prime mover", "Terminal voltage of the alternator (and sometimes reactive current for droop)", "Load current only", "Exciter output"], "exp": "AVR compares sensed terminal voltage against setpoint. Error signal adjusts field current. Some AVRs also use reactive current droop feedback for parallel operation stability.", "id": "T01_Alternator_Q051", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "Which protection trips immediately on large overcurrent (instantaneous)?", "a": "Short circuit/overcurrent instantaneous element of ACB", "opts": ["Reverse power relay", "Short circuit/overcurrent instantaneous element of ACB", "Undervoltage relay", "Earth fault relay"], "exp": "Instantaneous overcurrent (typically 8\u201310\u00d7 rated current) operates the ACB trip without intentional time delay \u2014 for bus bar faults. IDMT overcurrent has time delay for grading.", "id": "T01_Alternator_Q052", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is meant by 'reactive droop compensation' in AVR?", "a": "AVR reduces excitation slightly as reactive current increases, enabling stable sharing of kVAR between parallel generators", "opts": ["Generator reduces output voltage automatically", "AVR reduces excitation slightly as reactive current increases, enabling stable sharing of kVAR between parallel generators", "Frequency droop for active power", "Voltage drop protection"], "exp": "Without reactive droop, parallel generators fight over reactive load. Droop compensation gives a slightly drooping V vs Q characteristic to ensure stable sharing.", "id": "T01_Alternator_Q053", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "What is the main advantage of static excitation over rotating exciter?", "a": "Faster response time for AVR control and no rotating exciter maintenance", "opts": ["Lower cost", "Faster response time for AVR control and no rotating exciter maintenance", "Better in humid conditions", "Higher output voltage"], "exp": "Static exciter (thyristor-controlled) has millisecond response vs seconds for rotating exciter \u2014 better for rapid load changes and transient voltage control.", "id": "T01_Alternator_Q054", "topic": "T01_Alternator", "cat": "WP"}, {"q": "How do you calculate synchronous speed?", "a": "NS = 120 \u00d7 f / P (RPM), where f=frequency in Hz, P=number of poles", "opts": ["NS = f \u00d7 P", "NS = 120 \u00d7 f / P (RPM), where f=frequency in Hz, P=number of poles", "NS = P \u00d7 f / 60", "NS = 60 \u00d7 f / P"], "exp": "For 4-pole, 50Hz: NS = 120\u00d750/4 = 1500 RPM. For 6-pole, 60Hz: NS = 120\u00d760/6 = 1200 RPM.", "id": "T01_Alternator_Q055", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What type of protection prevents circulating currents between two paralleled generators with slight voltage difference?", "a": "Reactive droop setting in AVR limits circulating reactive current", "opts": ["Earth fault relay", "Reactive droop setting in AVR limits circulating reactive current", "Overcurrent relay", "Reverse power relay"], "exp": "Small voltage difference causes reactive circulating current. AVR droop compensation limits this. Differential protection (not common on marine generators) would detect internal faults.", "id": "T01_Alternator_Q056", "topic": "T01_Alternator", "cat": "WP"}, {"q": "How do you safely remove a generator from parallel operation?", "a": "Transfer load to other generator(s), reduce kW to minimum, open breaker, shut down prime mover", "opts": ["Open breaker immediately", "Transfer load to other generator(s), reduce kW to minimum, open breaker, shut down prime mover", "Stop engine first", "Trip overcurrent relay"], "exp": "Never open breaker under heavy load \u2014 causes voltage spike and potential damage to loads. Always transfer load first, reduce kW to near zero (reverse power protection will trip if you go negative).", "id": "T01_Alternator_Q057", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'cold spare' vs 'hot spare' for standby generator?", "a": "Cold: off and cold; Hot: running and warm, ready to take load faster", "opts": ["Both mean the same", "Cold: off and cold; Hot: running and warm, ready to take load faster", "Cold: on bus at low power; Hot: on bus at full power", "Only cold spare used in marine practice"], "exp": "Hot standby: engine running, generator on bus at very low load or just spinning in sync \u2014 instant load pickup. Cold standby: stopped, needs start time. AMF bridges the gap for cold standby.", "id": "T01_Alternator_Q058", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of the power management system (PMS)?", "a": "Automatically manages generator start/stop, load sharing, fault response and load shedding", "opts": ["Only monitors power consumption", "Automatically manages generator start/stop, load sharing, fault response and load shedding", "Replaces the AVR", "Controls shore power only"], "exp": "PMS monitors total load, starts generators before overload, sheds non-essential loads on fault, manages parallel operation \u2014 reduces need for manual intervention in UMS operations.", "id": "T01_Alternator_Q059", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'earth fault' on a generator?", "a": "One or more phases of stator winding making electrical contact with the earthed frame", "opts": ["Open circuit in winding", "One or more phases of stator winding making electrical contact with the earthed frame", "Short between two phases", "Broken field connection"], "exp": "Earth fault: phase conductor contacts machine frame (which is earthed). Detected by earth fault relay (usually 64 relay). On high-resistance earthed systems, fault current is limited.", "id": "T01_Alternator_Q060", "topic": "T01_Alternator", "cat": "PR"}, {"q": "What is the construction difference between salient pole and cylindrical rotor alternator?", "a": "Salient: protruding poles (low speed, multi-pole), Cylindrical: smooth rotor (high speed, 2-4 poles)", "opts": ["Both are the same", "Salient: protruding poles (low speed, multi-pole), Cylindrical: smooth rotor (high speed, 2-4 poles)", "Salient is for AC, cylindrical for DC", "Salient used for HV, cylindrical for LV"], "exp": "Marine diesel-driven: salient pole (slow speed, 6-12 poles). Steam turbine driven: cylindrical (high speed, 2-4 poles). Both are synchronous machines.", "id": "T01_Alternator_Q061", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is a 'dead bus' synchronisation?", "a": "Closing generator onto a dead (de-energised) busbar \u2014 no synchronisation needed", "opts": ["Synchronising two running generators", "Closing generator onto a dead (de-energised) busbar \u2014 no synchronisation needed", "Backup synchronisation method", "Synchronising at zero speed"], "exp": "Dead bus: just check that busbar is truly dead, confirm polarity and phase sequence, then close breaker. No synchroscope needed since there's nothing to synchronise to.", "id": "T01_Alternator_Q062", "topic": "T01_Alternator", "cat": "SY"}, {"q": "Alternator maintenance schedule \u2014 what is checked at 250 running hours?", "a": "Check connections, clean air filters, check bearing temperatures, record insulation values", "opts": ["Replace all bearings", "Check connections, clean air filters, check bearing temperatures, record insulation values", "Full overhaul", "Check only the ACB"], "exp": "Typical 250-hour PM: visual inspection, clean air passages, check and tighten connections, take IR reading, check bearing temperature/vibration trend, check cooler condition.", "id": "T01_Alternator_Q063", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What safety precautions before working on an alternator?", "a": "Isolate main breaker, lock out and tag, prove dead, discharge capacitors, permit to work", "opts": ["Only switch off breaker", "Isolate main breaker, lock out and tag, prove dead, discharge capacitors, permit to work", "Only put up warning signs", "Work with one hand only"], "exp": "Full LOTO procedure. For large generators: wait for rotor to stop completely. Discharge any capacitors in AVR circuit. Earth the stator terminals before working.", "id": "T01_Alternator_Q064", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the function of a 'trimmer' potentiometer in the AVR?", "a": "Allows fine adjustment of output voltage setpoint", "opts": ["Adjusts frequency", "Allows fine adjustment of output voltage setpoint", "Controls exciter speed", "Sets overcurrent threshold"], "exp": "Trimmer on AVR panel allows \u00b15% voltage adjustment. Used to equalise voltage between two generators before synchronising and for reactive power sharing adjustment.", "id": "T01_Alternator_Q065", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "What is the purpose of a capacitor in the AVR sensing circuit?", "a": "Filters out harmonics and smooths the sensed voltage signal", "opts": ["Stores energy for AVR", "Filters out harmonics and smooths the sensed voltage signal", "Powers AVR electronics", "Provides excitation"], "exp": "Harmonics in terminal voltage (from non-linear loads like VFDs) can cause AVR instability. Input filter capacitors smooth the sensing signal.", "id": "T01_Alternator_Q066", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "How does the load sharing panel enable load sharing between generators?", "a": "Provides cross-current compensation \u2014 generators with higher load feed signal to others to increase their load", "opts": ["Directly controls fuel injection", "Provides cross-current compensation \u2014 generators with higher load feed signal to others to increase their load", "Only monitors, does not control", "Controls both kW and kVAR automatically without droop"], "exp": "Cross-current compensation (circulating current method) allows reactive load sharing without droop \u2014 preferred for generators in permanent parallel operation.", "id": "T01_Alternator_Q067", "topic": "T01_Alternator", "cat": "LS"}, {"q": "What is the purpose of an overvoltage relay on an alternator?", "a": "Trips generator if output voltage exceeds safe limit (typically 110% of rated)", "opts": ["Trips on undervoltage", "Trips generator if output voltage exceeds safe limit (typically 110% of rated)", "Monitors AVR output", "Resets after fault"], "exp": "Overvoltage could damage loads, especially sensitive electronics. OV relay (typically set at 110%) trips generator breaker. AVR failure causing field forcing is common cause.", "id": "T01_Alternator_Q068", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What does a power factor meter on the switchboard indicate?", "a": "Ratio of active power (kW) to apparent power (kVA) \u2014 cos \u03c6", "opts": ["Generator efficiency", "Ratio of active power (kW) to apparent power (kVA) \u2014 cos \u03c6", "Phase voltage", "Reactive power only"], "exp": "PF meter: typically reads 0\u20131 lagging/leading. Most ship loads are inductive (lagging PF 0.8\u20130.9). Running generators at very low PF is inefficient and stresses the machine.", "id": "T01_Alternator_Q069", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the difference between KW and KVA?", "a": "KW = actual useful power; KVA = apparent power including reactive component; KW = KVA \u00d7 PF", "opts": ["No difference", "KW = actual useful power; KVA = apparent power including reactive component; KW = KVA \u00d7 PF", "KVA is larger only at 50 Hz", "KW is always greater than KVA"], "exp": "KVA\u00b2 = KW\u00b2 + KVAR\u00b2. At PF = 1.0, KVA = KW. At PF = 0.8, 1000 kVA delivers only 800 kW. Generator is rated in kVA because stator current (heating) depends on total current, not just active component.", "id": "T01_Alternator_Q070", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of the temperature detector (PT100) in the alternator stator?", "a": "Monitors winding temperature to prevent insulation overheating; triggers alarm and trip", "opts": ["Controls AVR output", "Monitors winding temperature to prevent insulation overheating; triggers alarm and trip", "Measures ambient temperature", "Controls cooling fan"], "exp": "PT100s embedded in stator slots sense winding temperature. Typical alarm: 120\u00b0C, trip: 155\u00b0C for Class F insulation. Trend monitoring is important for early fault detection.", "id": "T01_Alternator_Q071", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'magnetic flux' in an alternator?", "a": "The total magnetic field produced by the field winding, measured in Webers", "opts": ["Electrical current in winding", "The total magnetic field produced by the field winding, measured in Webers", "Voltage across stator", "Air gap dimension"], "exp": "Flux density (Tesla) \u00d7 Area = flux (Weber). Faraday's law: EMF = N \u00d7 d\u03a6/dt. Stronger field = higher voltage output (basis of AVR control).", "id": "T01_Alternator_Q072", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the purpose of harmonic filters on modern ship generators?", "a": "Reduce voltage distortion caused by non-linear loads like VFDs, UPS, and rectifiers", "opts": ["Increase output voltage", "Reduce voltage distortion caused by non-linear loads like VFDs, UPS, and rectifiers", "Filter DC ripple from exciter", "Improve bearing life"], "exp": "Non-linear loads draw non-sinusoidal currents, causing harmonic voltages. Harmonics cause overheating, AVR instability, and interference with electronics. Filters (passive L-C or active) reduce THD.", "id": "T01_Alternator_Q073", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the SOLAS requirement for emergency source of power on cargo ships?", "a": "SOLAS II-1/43: must supply for minimum 18 hours with specified services", "opts": ["3 hours", "18 hours", "24 hours", "12 hours"], "exp": "SOLAS II-1/43.2.1: cargo ships \u2014 emergency source must supply essential services for minimum 18 hours (passenger ships: 36 hours).", "id": "T01_Alternator_Q074", "topic": "T01_Alternator", "cat": "SOL"}, {"q": "How is the air gap of an alternator adjusted?", "a": "By shimming or adjusting bearing pedestals/end shields \u2014 requires major dismantling", "opts": ["By adjusting AVR", "By shimming or adjusting bearing pedestals/end shields \u2014 requires major dismantling", "By adding more stator copper", "Not adjustable on marine alternators"], "exp": "Air gap adjustment requires opening up the machine, removing rotor, shimming bearing housings. This is class/manufacturer-supervised work, typically done in drydock.", "id": "T01_Alternator_Q075", "topic": "T01_Alternator", "cat": "AG"}, {"q": "What are symptoms of an overloaded alternator?", "a": "High stator current, winding temperature rise, voltage drop despite AVR, possible tripping on overcurrent", "opts": ["Higher voltage output", "High stator current, winding temperature rise, voltage drop despite AVR, possible tripping on overcurrent", "Faster rotation", "Lower excitation needed"], "exp": "Overload \u2192 excessive stator current \u2192 I\u00b2R heating \u2192 insulation damage if prolonged. AVR tries to maintain voltage but may reach field current limit. Action: shed load or start another generator.", "id": "T01_Alternator_Q076", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What are the SOLAS requirements for main source of electrical power?", "a": "SOLAS II-1/41: maintain all services needed for normal operation and safety, survive any single failure", "opts": ["Any three phase supply", "SOLAS II-1/41: maintain all services needed for normal operation and safety, survive any single failure", "Supply lights and navigation only", "Not specified in SOLAS"], "exp": "SOLAS II-1/41: main electrical installation must supply all services under normal and emergency conditions. n+1 redundancy concept \u2014 losing any single generator must not affect essential services.", "id": "T01_Alternator_Q077", "topic": "T01_Alternator", "cat": "SOL"}, {"q": "What is the purpose of the 'dead man alarm' / UMS watchkeeping system?", "a": "Alerts bridge if no manual acknowledgement from ECR within set period \u2014 prevents unattended machinery failure going unnoticed", "opts": ["Detects generator overload", "Alerts bridge if no manual acknowledgement from ECR within set period \u2014 prevents unattended machinery failure going unnoticed", "Monitors bearing temperatures", "Controls power management"], "exp": "UMS (Unattended Machinery Space) regulations require dead man alarm \u2014 officer must acknowledge alarm every 30 minutes (varies by system) or bridge/general alarm sounds.", "id": "T01_Alternator_Q078", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is an 'earth leakage alarm' on the main switchboard?", "a": "Detects insulation leakage to earth in the IT (isolated) distribution system", "opts": ["Detects ACB earth fault", "Detects insulation leakage to earth in the IT (isolated) distribution system", "Monitors earthing resistance", "Trips all generators"], "exp": "Ship's distribution is typically IT (isolated from earth) allowing one fault without current flow. Earth leakage relay detects the first fault and alarms \u2014 no trip on first fault. Second fault = short circuit.", "id": "T01_Alternator_Q079", "topic": "T01_Alternator", "cat": "WP"}, {"q": "For what reason is the ship's electrical system typically isolated (not solidly earthed)?", "a": "Single earth fault does not cause shock hazard or trip supply \u2014 gives time to trace and rectify fault", "opts": ["To reduce energy consumption", "Single earth fault does not cause shock hazard or trip supply \u2014 gives time to trace and rectify fault", "Reduces lightning damage", "Required by flag state"], "exp": "IT (isolated) system: one fault = no current flows. Allows continued operation while fault is traced. Two simultaneous faults on different phases = direct short circuit \u2014 hence earth fault alarm is critical.", "id": "T01_Alternator_Q080", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the typical no-load voltage droop percentage allowed in AVR specification?", "a": "\u00b11% of nominal voltage", "opts": ["\u00b110%", "\u00b15%", "\u00b11% of nominal voltage", "\u00b10.1%"], "exp": "Good AVR specification: voltage regulation \u22641% at no-load to full-load. Response time: <1 second for 10% load change. Modern digital AVRs achieve \u00b10.5% regulation.", "id": "T01_Alternator_Q081", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "What are rotating diodes tested with?", "a": "Multimeter on diode test function, or ohmmeter \u2014 check forward voltage drop and no reverse conduction", "opts": ["Megger 500V", "Multimeter on diode test function, or ohmmeter \u2014 check forward voltage drop and no reverse conduction", "High voltage tester", "Insulation tester"], "exp": "Rotating diodes: check with multimeter in diode mode. Forward: ~0.6V drop (silicon). Reverse: open circuit (OL). Short: 0 both ways. Open: OL both ways. Test with rotor stationary and diodes accessible.", "id": "T01_Alternator_Q082", "topic": "T01_Alternator", "cat": "BL"}, {"q": "What protection is provided by the 'negative sequence' relay?", "a": "Detects unbalanced phase currents (often due to open circuit or single-phase loading)", "opts": ["Detects reverse power", "Detects unbalanced phase currents (often due to open circuit or single-phase loading)", "Measures negative voltage", "Trips on undervoltage"], "exp": "Negative sequence components arise from asymmetrical faults or loads. Cause dangerous rotor overheating in synchronous machines. Negative sequence relay (46) protects large generators.", "id": "T01_Alternator_Q083", "topic": "T01_Alternator", "cat": "WP"}, {"q": "How many main generators does a typical merchant ship have?", "a": "Usually 3 generators (2 running for sea passage, 1 standby; 3 running in port for heavy loads)", "opts": ["Always 1", "Always 2", "Usually 3 generators (2 running for sea passage, 1 standby; 3 running in port for heavy loads)", "Minimum 4"], "exp": "Configuration varies: 3 is most common \u2014 provides N+1 redundancy. Large ships may have 4 or more. Some modern ships have shaft generator as primary with 2 auxiliaries.", "id": "T01_Alternator_Q084", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'excitation current' in an alternator?", "a": "DC current fed to field winding to create magnetic flux for voltage generation", "opts": ["AC current in stator", "DC current fed to field winding to create magnetic flux for voltage generation", "Current to power AVR", "Earth current"], "exp": "Field (excitation) current: typically 5\u201320A DC for small generators, up to 100A+ for large machines. Controls magnetic flux \u2192 controls output voltage \u2192 controlled by AVR.", "id": "T01_Alternator_Q085", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What happens when a generator's AVR fails in the 'full field' position?", "a": "Generator output voltage rises rapidly, overvoltage trips, equipment potentially damaged", "opts": ["Generator shuts down safely", "Generator output voltage rises rapidly, overvoltage trips, equipment potentially damaged", "No change \u2014 another AVR takes over", "Voltage drops to zero"], "exp": "AVR fail to full field = field forcing \u2192 voltage shoots up \u2192 overvoltage relay should trip generator breaker \u2192 if OV relay fails, loads and insulation are at risk.", "id": "T01_Alternator_Q086", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "How do you determine which of two paralleled generators has the higher load?", "a": "Read kW meters on switchboard for each generator", "opts": ["Check fuel consumption", "Read kW meters on switchboard for each generator", "Compare AVR settings", "Check engine temperature"], "exp": "kW meters directly indicate active power sharing. For reactive sharing, check kVAR meters or power factor meters. Adjust governors for kW, AVR trimmers for kVAR.", "id": "T01_Alternator_Q087", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'voltage build-up' in an alternator?", "a": "Process by which residual magnetism induces initial voltage, which excites field further, bootstrapping to rated voltage", "opts": ["Process of AVR initialisation", "Process by which residual magnetism induces initial voltage, which excites field further, bootstrapping to rated voltage", "Battery charging process", "Field current test process"], "exp": "Residual flux \u2192 small induced EMF \u2192 AVR senses \u2192 increases field current \u2192 more flux \u2192 more EMF \u2192 builds up to rated voltage. If residual magnetism lost, no build-up \u2014 flash the field.", "id": "T01_Alternator_Q088", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'reactive power' and how is it produced in an alternator?", "a": "Non-working power stored/released by reactive elements (inductors/capacitors); produced by increasing excitation", "opts": ["Power lost as heat", "Non-working power stored/released by reactive elements (inductors/capacitors); produced by increasing excitation", "Power consumed by resistance", "Same as active power"], "exp": "Reactive power (kVAR) circulates between source and reactive loads without doing work. Inductive loads absorb reactive power; alternator supplies it by being 'over-excited' (field current above normal).", "id": "T01_Alternator_Q089", "topic": "T01_Alternator", "cat": "LS"}, {"q": "How is an alternator cooled in marine applications?", "a": "Self-ventilation (fan on rotor), forced air cooling, or closed circuit water cooler (TEWAC)", "opts": ["Only by ambient air", "Self-ventilation (fan on rotor), forced air cooling, or closed circuit water cooler (TEWAC)", "Only water cooling", "External fan only"], "exp": "TEWAC (Totally Enclosed Water-Air Cooled): internal air circulates through water-cooled heat exchanger \u2014 no engine room air enters winding. Good protection against salt-laden, humid marine air.", "id": "T01_Alternator_Q090", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What records must be kept for generator maintenance?", "a": "Running hours, IR readings, bearing temperatures, maintenance done, faults, test results \u2014 in PMS and logbook", "opts": ["Only running hours", "Running hours, IR readings, bearing temperatures, maintenance done, faults, test results \u2014 in PMS and logbook", "Only fault records", "Only class-required records"], "exp": "Good records enable trend analysis (deteriorating IR = impending insulation failure), demonstrate compliance to class surveyor, support planned maintenance intervals.", "id": "T01_Alternator_Q091", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'field current limit' in AVR?", "a": "Maximum excitation current allowed \u2014 prevents overheating of field winding", "opts": ["Maximum stator current", "Maximum excitation current allowed \u2014 prevents overheating of field winding", "Minimum field current for AVR", "Current limit for AVR electronics"], "exp": "If load demands more reactive power than field can supply, AVR hits field current limit. Terminal voltage then drops. Underexcitation limit (UEL) prevents loss of synchronism.", "id": "T01_Alternator_Q092", "topic": "T01_Alternator", "cat": "AVR"}, {"q": "What action if two paralleled generators have different frequencies (slightly)?", "a": "Adjust governor of the off-speed machine \u2014 they must run at same synchronous frequency", "opts": ["Adjust AVR", "Adjust governor of the off-speed machine \u2014 they must run at same synchronous frequency", "Open breaker of faster one", "Acceptable \u2014 no action needed"], "exp": "In parallel, both machines are locked at same bus frequency. Speed difference shows as circulating currents. Adjust governor on faster/slower machine to achieve equal governor settings and stable operation.", "id": "T01_Alternator_Q093", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the standard voltage for ship's emergency lighting?", "a": "Typically 220V single phase AC or 24V DC (battery backed)", "opts": ["440V 3-phase", "110V DC only", "Typically 220V single phase AC or 24V DC (battery backed)", "Always 24V DC"], "exp": "Emergency lighting fed from emergency switchboard (220V from emergency gen) and additionally from independent battery-backed sources for specific areas per SOLAS.", "id": "T01_Alternator_Q094", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is 'generator earthing' and why is it done?", "a": "Connecting generator neutral/frame to earth to control touch voltage and assist fault detection", "opts": ["Connecting output to earth for safety", "Connecting generator neutral/frame to earth to control touch voltage and assist fault detection", "Not used on ships", "Connects to ship's hull only"], "exp": "Marine generators typically isolated (IT system) \u2014 frame earthed for safety, but neutral not solidly earthed. HV generators use high-resistance neutral earthing (NER) to limit earth fault current.", "id": "T01_Alternator_Q095", "topic": "T01_Alternator", "cat": "WP"}, {"q": "What is the fundamental principle on which an alternator works?", "a": "Electromagnetic induction (Faraday's Law)", "opts": ["Mutual inductance", "Electromagnetic induction (Faraday's Law)", "Lenz's Law", "Fleming's right hand rule"], "exp": "Faraday's Law: EMF is induced in a conductor when there is a relative change in magnetic flux. In an alternator, the rotating DC-excited rotor field cuts the stator conductors, inducing AC EMF.", "cat": "WP", "id": "T01_EX_095", "topic": "T01_Alternator"}, {"q": "In a marine alternator, which part rotates and which is stationary?", "a": "Rotor carries DC field winding (rotates); stator carries AC output winding (stationary)", "opts": ["Both rotor and stator rotate", "Stator carries field winding; rotor carries output winding", "Rotor carries DC field winding (rotates); stator carries AC output winding (stationary)", "Both are stationary and EMF is induced by flux changes"], "exp": "The rotor field (DC-excited) rotates driven by the prime mover. The stator winding is fixed and has AC induced in it. Output is taken from the stationary stator \u2014 no brushes on output side.", "cat": "WP", "id": "T01_EX_096", "topic": "T01_Alternator"}, {"q": "Why is an alternator rated in kVA and not kW?", "a": "Winding heating depends on current (kVA), which is independent of load power factor", "opts": ["kVA is a larger number making the rating look impressive", "Because alternators cannot supply real power", "Winding heating depends on current (kVA), which is independent of load power factor", "kW rating only applies to DC machines"], "exp": "Winding copper losses (I\u00b2R heating) depend only on current magnitude, regardless of whether the load is resistive or reactive. Since kVA = V \u00d7 I, and heating is determined by I, the alternator is rated in kVA \u2014 it doesn't know the power factor of the load.", "cat": "WP", "id": "T01_EX_097", "topic": "T01_Alternator"}, {"q": "What determines the output frequency of a marine alternator?", "a": "f = (N \u00d7 P) / 120, where N = RPM and P = number of poles", "opts": ["Only the excitation voltage", "Only the load connected to it", "f = (N \u00d7 P) / 120, where N = RPM and P = number of poles", "The AVR setting"], "exp": "Frequency is set by mechanical speed and pole pairs. For 60 Hz at 4 poles: N = 1800 RPM. For 50 Hz at 4 poles: N = 1500 RPM. This is why governor control maintains constant frequency.", "cat": "WP", "id": "T01_EX_098", "topic": "T01_Alternator"}, {"q": "In a separately excited alternator, where does the field excitation come from?", "a": "External DC source supplied via slip rings", "opts": ["The alternator supplies its own field via rectifier", "External DC source supplied via slip rings", "The permanent magnets on the rotor", "A battery bank connected permanently"], "exp": "Separately excited means DC field current is supplied from an external source (battery, rectifier) through slip rings. Problem: requires slip rings and brushes, causing maintenance issues in marine environments.", "cat": "EX", "id": "T01_EX_099", "topic": "T01_Alternator"}, {"q": "In a self-excited shunt alternator, what provides the initial excitation?", "a": "Residual magnetism in the rotor core", "opts": ["A separate battery charger", "The PMG unit", "Residual magnetism in the rotor core", "Shore supply rectifier"], "exp": "Residual magnetism induces a small initial voltage \u2192 this feeds back to field winding \u2192 field builds up \u2192 voltage builds up. This 'bootstrap' process builds voltage from zero. If residual magnetism is lost, flashing is needed.", "cat": "EX", "id": "T01_EX_100", "topic": "T01_Alternator"}, {"q": "What are the THREE machines mounted on the same shaft in a brushless alternator system?", "a": "PMG (Permanent Magnet Generator), Main Exciter, Main Alternator", "opts": ["AVR, Exciter, Main Alternator", "PMG (Permanent Magnet Generator), Main Exciter, Main Alternator", "Transformer, Rectifier, Generator", "Governor, Exciter, Alternator"], "exp": "All three rotate together on one shaft: (1) PMG \u2014 provides stable AC to feed AVR. (2) Main Exciter \u2014 stator is fed by AVR, rotor generates 3-phase AC. (3) Main Alternator \u2014 rotor field carries DC (from rotating rectifiers), stator gives 3-phase output.", "cat": "BL", "id": "T01_EX_101", "topic": "T01_Alternator"}, {"q": "What is the function of the PMG (Permanent Magnet Generator) in a brushless system?", "a": "Provides independent, stable AC power supply to the AVR", "opts": ["Directly excites the main alternator field", "Provides independent, stable AC power supply to the AVR", "Acts as backup generator during blackout", "Controls the speed of the prime mover"], "exp": "PMG uses permanent magnets, so its output is unaffected by main alternator voltage changes. It provides a clean, stable supply to the AVR. This means the AVR functions correctly even when the main alternator is in fault condition.", "cat": "BL", "id": "T01_EX_102", "topic": "T01_Alternator"}, {"q": "Why is the brushless alternator called 'brushless'?", "a": "No brushes or slip rings are needed to transfer current from stationary to rotating parts", "opts": ["It uses fewer windings than conventional alternators", "No brushes or slip rings are needed to transfer current from stationary to rotating parts", "The stator does not use carbon brush contacts", "It eliminates the need for a commutator"], "exp": "In a brushless design, the exciter field is on the stator (stationary), exciter armature is on the rotor. Rotating rectifiers on the shaft convert AC to DC without needing physical contact (no brushes/slip rings). DC goes directly to main field winding on the shaft.", "cat": "BL", "id": "T01_EX_103", "topic": "T01_Alternator"}, {"q": "What is the path of excitation current in a brushless alternator (correct sequence)?", "a": "PMG \u2192 AVR \u2192 Exciter field stator \u2192 Exciter rotor AC \u2192 Rotating diodes \u2192 Main field rotor \u2192 Main stator output", "opts": ["AVR \u2192 PMG \u2192 Rotating diodes \u2192 Main field", "Battery \u2192 Slip rings \u2192 Field winding \u2192 Output", "PMG \u2192 AVR \u2192 Exciter field stator \u2192 Exciter rotor AC \u2192 Rotating diodes \u2192 Main field rotor \u2192 Main stator output", "Governor \u2192 AVR \u2192 Stator \u2192 Rotor \u2192 Output"], "exp": "This is the complete brushless excitation chain. PMG generates AC \u2192 AVR rectifies and controls \u2192 DC fed to exciter stator field \u2192 exciter rotor generates 3-phase AC \u2192 rotating rectifier diodes convert to DC \u2192 DC field on main rotor \u2192 main stator cuts field \u2192 3-phase output.", "cat": "BL", "id": "T01_EX_104", "topic": "T01_Alternator"}, {"q": "Where are the rotating rectifier diodes physically located in a brushless alternator?", "a": "Mounted on the rotor shaft between the exciter armature and main field winding", "opts": ["Inside the AVR control panel", "On the stator frame near ventilation openings", "Mounted on the rotor shaft between the exciter armature and main field winding", "In a separate rectifier cabinet next to the alternator"], "exp": "Rotating rectifiers are a diode wheel mounted directly on the rotating shaft. They spin with the shaft, converting the exciter's 3-phase AC output to DC. Being on the shaft eliminates the need for slip rings \u2014 the DC stays within the rotating assembly.", "cat": "BL", "id": "T01_EX_105", "topic": "T01_Alternator"}, {"q": "What happens if ONE rotating rectifier diode goes OPEN CIRCUIT while the alternator is running?", "a": "Output voltage drops 15\u201320% with fluctuation; unbalanced excitation causes ripple", "opts": ["Complete loss of voltage \u2014 machine trips immediately", "Output voltage drops 15\u201320% with fluctuation; unbalanced excitation causes ripple", "No effect \u2014 remaining diodes compensate fully", "Frequency drops proportionally to voltage drop"], "exp": "With one open diode, one phase of the 3-phase exciter output is not rectified. The remaining diodes handle only partial DC. Result: DC ripple in field current \u2192 pulsating output voltage. Stroboscope check can detect discoloured/pitted diodes while running.", "cat": "BL", "id": "T01_EX_106", "topic": "T01_Alternator"}, {"q": "What happens if ONE rotating rectifier diode goes SHORT CIRCUIT while running?", "a": "AC component appears in field current causing severe voltage fluctuation and field overheating", "opts": ["Minor voltage fluctuation, self-corrects within minutes", "Generator shuts down automatically via thermal protection", "AC component appears in field current causing severe voltage fluctuation and field overheating", "Output becomes DC instead of AC"], "exp": "A shorted diode creates a reverse current path \u2014 AC flows through the short, superimposing on the DC field. This causes both severe output voltage fluctuation and dangerous heating in the field winding. Immediate action needed: shut down and inspect.", "cat": "BL", "id": "T01_EX_107", "topic": "T01_Alternator"}, {"q": "How do you detect a faulty rotating diode while the alternator is running?", "a": "Using a stroboscope \u2014 check for discoloured, pitted or cracked diodes; also check for unbalanced output voltage", "opts": ["Remove the diode cover and inspect with a torch", "Using a multimeter on the AC output terminals", "Using a stroboscope \u2014 check for discoloured, pitted or cracked diodes; also check for unbalanced output voltage", "Inject test voltage through the slip rings"], "exp": "A stroboscope freezes the apparent rotation of the diode wheel, allowing visual inspection while running. Faulty diodes show discolouration or pitting. Electrical symptoms: ripple on output voltage, unbalanced 3-phase voltage. Confirm by shutdown and diode test.", "cat": "BL", "id": "T01_EX_108", "topic": "T01_Alternator"}, {"q": "What is the primary function of the AVR (Automatic Voltage Regulator)?", "a": "Automatically maintains alternator terminal voltage at set value by adjusting excitation current", "opts": ["Controls the speed of the prime mover", "Automatically maintains alternator terminal voltage at set value by adjusting excitation current", "Protects the alternator from short circuit", "Monitors and logs alternator performance data"], "exp": "AVR continuously senses output voltage, compares it to the setpoint, and adjusts field current via thyristors/transistors to keep voltage constant. If voltage drops (more load added), AVR increases field current. If voltage rises (load removed), it reduces field current.", "cat": "AVR", "id": "T01_EX_109", "topic": "T01_Alternator"}, {"q": "According to SOLAS, what is the steady-state voltage regulation requirement for marine alternators?", "a": "Within \u00b12.5% of rated voltage from no-load to full-load", "opts": ["Within \u00b15% of rated voltage", "Within \u00b11% of rated voltage", "Within \u00b12.5% of rated voltage from no-load to full-load", "Within \u00b110% during any transient condition"], "exp": "SOLAS Ch. II-1/Reg 40.3: Steady-state voltage must be maintained within \u00b12.5% of rated voltage under any load condition from no-load to full-load. Transient deviation must not exceed \u00b110% before recovering to \u00b12.5%.", "cat": "SOL", "id": "T01_EX_110", "topic": "T01_Alternator"}, {"q": "What is the maximum transient voltage excursion allowed by SOLAS during sudden load changes?", "a": "\u00b110% of rated voltage, recovering within required time", "opts": ["\u00b12.5% \u2014 same as steady state", "\u00b15% maximum", "\u00b110% of rated voltage, recovering within required time", "\u00b115% is acceptable for heavy loads"], "exp": "SOLAS allows up to \u00b110% transient excursion on sudden load pickup or shedding \u2014 this accounts for the AVR response time. The voltage must then recover to within \u00b12.5% steady-state band. This is tested during load acceptance trials.", "cat": "SOL", "id": "T01_EX_111", "topic": "T01_Alternator"}, {"q": "Why must the AVR be DISCONNECTED before performing a megger (IR) test on the alternator?", "a": "Megger voltage (500\u20131000V DC) can permanently damage AVR semiconductors (thyristors, transistors, capacitors)", "opts": ["To prevent the AVR from showing false readings on the display", "Megger voltage (500\u20131000V DC) can permanently damage AVR semiconductors (thyristors, transistors, capacitors)", "To allow manual field control during testing", "AVR will reverse the polarity of megger readings"], "exp": "The megger applies 500\u20131000V DC to the winding. AVR contains sensitive solid-state components rated for much lower voltages. Also, the AVR may back-feed current into the winding, giving a false (higher) IR reading. Always disconnect and short AVR terminals before meggering.", "cat": "AVR", "id": "T01_EX_112", "topic": "T01_Alternator"}, {"q": "What is the 'Voltage Adjust' trimmer in an AVR used for?", "a": "Sets the output voltage setpoint (e.g., 440V) of the alternator", "opts": ["Sets the maximum current limit", "Sets the output voltage setpoint (e.g., 440V) of the alternator", "Controls the frequency trim", "Adjusts the reactive load sharing between parallel generators"], "exp": "The voltage adjust trimmer sets the reference setpoint that AVR tries to maintain. Turning it up \u2192 field current increases \u2192 terminal voltage rises. This is adjusted during commissioning to set exactly 440V (or 6600V on HV ships).", "cat": "AVR", "id": "T01_EX_113", "topic": "T01_Alternator"}, {"q": "What is the 'Droop' trimmer in the AVR used for?", "a": "Sets the reactive power (kVAR) sharing between generators running in parallel", "opts": ["Reduces output voltage gradually under heavy load for safety", "Sets the reactive power (kVAR) sharing between generators running in parallel", "Adjusts governor response speed", "Controls frequency droop for kW sharing"], "exp": "AVR droop causes the terminal voltage to slightly decrease as reactive (kVAR) load increases. When two machines are in parallel, this ensures equal kVAR sharing. Without droop, one AVR 'wins' and supplies all reactive current \u2014 other machine runs at near unity PF or capacitive.", "cat": "AVR", "id": "T01_EX_114", "topic": "T01_Alternator"}, {"q": "What is residual magnetism in an alternator?", "a": "Small amount of magnetic flux retained in rotor core material even when field current is zero", "opts": ["The permanent magnetic field used in synchronous operation", "Small amount of magnetic flux retained in rotor core material even when field current is zero", "Static charge on stator windings after shutdown", "The minimum field current required to start voltage buildup"], "exp": "Rotor core material retains some magnetism after the field current is removed. This residual flux induces a small initial voltage during run-up. The self-excited alternator uses this to bootstrap its own voltage. If lost (e.g., by a large external discharge), flashing is needed.", "cat": "RM", "id": "T01_EX_115", "topic": "T01_Alternator"}, {"q": "An alternator runs at rated RPM but shows zero voltage on the voltmeter. What are the possible causes?", "a": "Residual magnetism lost, AVR fault, rotating diode failure, PMG fault, open circuit field winding, or voltmeter fault", "opts": ["Only the governor has failed", "Residual magnetism lost, AVR fault, rotating diode failure, PMG fault, open circuit field winding, or voltmeter fault", "Always means the stator winding is burnt", "Caused by wrong phase rotation only"], "exp": "Systematic check: (1) Is voltmeter accurate? (2) Residual magnetism \u2014 try flashing. (3) Check AVR supply and function. (4) Check PMG output. (5) Check rotating diodes. (6) Measure field winding resistance. Multiple causes \u2014 systematic elimination is key.", "cat": "RM", "id": "T01_EX_116", "topic": "T01_Alternator"}, {"q": "What is the procedure for FLASHING an alternator?", "a": "Bring to rated speed; connect 12\u201324V battery briefly (2\u20133 sec) to exciter field with correct polarity; check voltage builds", "opts": ["Apply 415V AC from shore supply to the stator terminals", "Bring to rated speed; connect 12\u201324V battery briefly (2\u20133 sec) to exciter field with correct polarity; check voltage builds", "Use megger at 500V to restore magnetism in rotor core", "Short circuit the AVR output terminals for 5 seconds"], "exp": "Flashing uses a DC battery to restore the residual magnetism in the rotor. CRITICAL: correct polarity must be maintained. Reverse polarity will destroy the residual magnetism further. Connect only 2\u20133 seconds \u2014 longer connection risks winding damage. Check voltage builds up as soon as battery is disconnected.", "cat": "RM", "id": "T01_EX_117", "topic": "T01_Alternator"}, {"q": "What is the main risk during a flashing operation?", "a": "Wrong polarity destroys residual magnetism; battery sparking can ignite flammable gases", "opts": ["Overvoltage in the stator winding", "Wrong polarity destroys residual magnetism; battery sparking can ignite flammable gases", "AVR permanent damage from battery voltage", "Voltmeter burning out from sudden voltage surge"], "exp": "Risk 1: Reversed polarity \u2192 residual magnetism is demagnetised further \u2192 harder to restore. Risk 2: Battery spark at connection/disconnection. A fire extinguisher must be nearby. Also ensure all personnel are clear of rotating parts before starting.", "cat": "RM", "id": "T01_EX_118", "topic": "T01_Alternator"}, {"q": "How do you ensure an alternator is electrically safe (dead) when residual magnetism may still be present?", "a": "Measure terminal voltage with an approved voltmeter before working \u2014 do not assume dead just because ACB is open", "opts": ["If ACB is open, machine is always dead \u2014 no further check needed", "Only use it if it's been switched off for over 30 minutes", "Measure terminal voltage with an approved voltmeter before working \u2014 do not assume dead just because ACB is open", "Remove all three phases from the busbar simultaneously"], "exp": "Residual magnetism means a small voltage IS present at stator terminals even with ACB open and no field current. This can cause shock. Always verify with a voltmeter before working on stator terminals. Earth the machine if necessary for complete safety.", "cat": "RM", "id": "T01_EX_119", "topic": "T01_Alternator"}, {"q": "What does a synchroscope indicate?", "a": "Speed difference and phase angle difference between incoming generator and the running busbar", "opts": ["Only the voltage difference between two generators", "The total load on the busbar", "Speed difference and phase angle difference between incoming generator and the running busbar", "The power factor of the incoming generator"], "exp": "Synchroscope is a phase-difference measuring instrument. It shows: (1) CW rotation = incoming machine too fast. (2) CCW rotation = too slow. (3) Pointer position = phase angle between incoming and busbar. Close ACB when pointer at 12 o'clock approaching slowly CW.", "cat": "SY", "id": "T01_EX_120", "topic": "T01_Alternator"}, {"q": "Describe the construction of a synchroscope.", "a": "Small induction motor: stator connected to busbar, rotor connected to incoming generator, pointer mounted on rotor shaft", "opts": ["An electronic digital phase meter", "A galvanometer measuring voltage difference", "Small induction motor: stator connected to busbar, rotor connected to incoming generator, pointer mounted on rotor shaft", "A current transformer connected across two generators"], "exp": "Synchroscope stator creates rotating magnetic field from busbar supply. Incoming generator supply feeds the rotor. Relative speed/phase difference makes rotor (and pointer) spin. At synchronism, rotor field and stator field lock \u2192 pointer stops at 12 o'clock.", "cat": "SY", "id": "T01_EX_121", "topic": "T01_Alternator"}, {"q": "When should the ACB be closed during synchronisation using a synchroscope?", "a": "When pointer is at 12 o'clock (in phase) and approaching from slightly before 12 (CW \u2014 just fast)", "opts": ["When pointer is at 6 o'clock for safety margin", "When pointer stops moving completely", "When pointer is at 12 o'clock (in phase) and approaching from slightly before 12 (CW \u2014 just fast)", "When pointer is at 3 o'clock position"], "exp": "Close ACB just BEFORE the pointer reaches 12, while it moves slowly CW. This ensures the incoming generator takes load immediately (rather than motoring). If closed exactly at 12 but slightly slow (CCW), the machine will briefly motor before taking load.", "cat": "SY", "id": "T01_EX_122", "topic": "T01_Alternator"}, {"q": "What happens if the ACB is closed when the synchroscope pointer is at 6 o'clock (180\u00b0 out of phase)?", "a": "CATASTROPHIC \u2014 massive circulating current, severe mechanical shock to coupling, possible alternator winding burnout", "opts": ["The generator safely comes up to speed on the busbar", "A minor overcurrent trip occurs", "CATASTROPHIC \u2014 massive circulating current, severe mechanical shock to coupling, possible alternator winding burnout", "The reverse power relay trips the circuit safely"], "exp": "180\u00b0 out of phase means two generators are directly opposing each other. The effective voltage causing circulating current = 2 \u00d7 Vline \u2248 880V across internal impedances. Current is extremely high \u2014 enough to instantly burn windings and cause severe mechanical shock to shafts and couplings.", "cat": "SY", "id": "T01_EX_123", "topic": "T01_Alternator"}, {"q": "What happens if the incoming generator is running FASTER than the busbar (synchroscope rotating CW)?", "a": "On closing ACB, incoming generator takes a heavy sudden load \u2014 high current surge, may trip on overcurrent", "opts": ["Generator immediately synchronises perfectly", "On closing ACB, incoming generator takes a heavy sudden load \u2014 high current surge, may trip on overcurrent", "Reverse power relay trips the incoming machine", "Frequency of the busbar increases to match"], "exp": "Too fast = incoming is ahead in phase. When ACB closes, the incoming generator tries to 'push' current into the busbar. It immediately takes a heavy load surge. If too fast, the surge current may trip OCR. This is why speed should be just slightly fast \u2014 not excessively so.", "cat": "SY", "id": "T01_EX_124", "topic": "T01_Alternator"}, {"q": "What happens if the incoming generator is running SLOWER than the busbar (synchroscope rotating CCW)?", "a": "On closing ACB, the busbar motors the incoming generator \u2014 reverse power relay trips it", "opts": ["Nothing \u2014 generator continues at lower speed", "The governor automatically speeds up", "On closing ACB, the busbar motors the incoming generator \u2014 reverse power relay trips it", "The busbar frequency drops to match"], "exp": "Too slow = incoming is behind in phase. When ACB closes, the running generator (busbar side) back-feeds power into the incoming generator, which runs as a motor. Reverse power relay detects this backward power flow and trips the ACB.", "cat": "SY", "id": "T01_EX_125", "topic": "T01_Alternator"}, {"q": "The synchroscope is faulty. How will you parallel the alternator?", "a": "Dark lamp method: connect 3 lamps between corresponding phases; close ACB when ALL THREE lamps are simultaneously dark", "opts": ["Estimate by ear \u2014 match engine speed to busbar frequency", "Use voltmeter across ACB contacts; close when voltage difference is minimum", "Dark lamp method: connect 3 lamps between corresponding phases; close ACB when ALL THREE lamps are simultaneously dark", "Wait for superintendent to arrive with portable synchroscope"], "exp": "Dark lamp: lamps glow when phases are out of sync, dim to darkness when in phase. Close when ALL three dark simultaneously. Alternative: Bright lamp (lamps connected in sequence) \u2014 close when all three equally bright. Dark lamp is more common in practice.", "cat": "SY", "id": "T01_EX_126", "topic": "T01_Alternator"}, {"q": "What is the phase sequence check done BEFORE paralleling two generators?", "a": "Verify both generators have the same phase rotation sequence (R-Y-B) using a phase sequence meter", "opts": ["Check frequency only \u2014 phase sequence doesn't matter for paralleling", "Verify both generators have the same phase rotation sequence (R-Y-B) using a phase sequence meter", "Measure the voltage at all three phases", "Check the insulation resistance of both machines"], "exp": "Phase sequence MUST be identical. If wrong phase sequence is used, even when synchroscope shows 12 o'clock, there's actually a 120\u00b0 voltage difference between phases \u2014 causes large circulating current when ACB is closed. Always verify phase sequence on new or rewound generators.", "cat": "SY", "id": "T01_EX_127", "topic": "T01_Alternator"}, {"q": "In parallel generators, what controls ACTIVE POWER (kW) sharing?", "a": "Governor droop settings \u2014 governor controls prime mover speed and thus kW output", "opts": ["AVR voltage setting", "Governor droop settings \u2014 governor controls prime mover speed and thus kW output", "Frequency relay settings", "Preferential trip relay"], "exp": "kW (active power) sharing is purely a function of speed/frequency. The governor controls diesel engine fuel injection \u2014 more fuel = more torque = more kW. Droop setting ensures when one machine takes more kW, its speed slightly drops, prompting the governor to back off.", "cat": "LS", "id": "T01_EX_128", "topic": "T01_Alternator"}, {"q": "In parallel generators, what controls REACTIVE POWER (kVAR) and power factor sharing?", "a": "AVR droop settings \u2014 AVR controls excitation and thus reactive current sharing", "opts": ["Governor speed settings", "Load shedding relay", "AVR droop settings \u2014 AVR controls excitation and thus reactive current sharing", "Synchroscope position"], "exp": "kVAR (reactive power) is controlled by excitation (field current). More excitation \u2192 higher terminal voltage \u2192 machine pushes out more reactive current (inductive kVAR). AVR droop ensures equal kVAR sharing: as one machine takes more kVAR, its voltage slightly drops, signalling AVR to reduce excitation.", "cat": "LS", "id": "T01_EX_129", "topic": "T01_Alternator"}, {"q": "Two generators running in parallel: G1 shows 600 kW, G2 shows 200 kW. What is the problem?", "a": "Unequal active (kW) load sharing \u2014 governor droop settings differ or governor trimmer needs adjusting", "opts": ["AVR is faulty on G2", "Unequal active (kW) load sharing \u2014 governor droop settings differ or governor trimmer needs adjusting", "Phase sequence is wrong", "Synchroscope has failed"], "exp": "Unequal kW means governors are not equally sharing the load. Check: (1) Governor droop settings equal on both. (2) If electronic governor \u2014 check speed trimmer. (3) If mechanical \u2014 check speeder spring. Adjust trimmer on the overloaded machine to reduce its kW.", "cat": "WP", "id": "T01_EX_130", "topic": "T01_Alternator"}, {"q": "Two generators running in parallel: kW output is equal but current differs. What is the cause?", "a": "Unequal reactive (kVAR) load sharing \u2014 AVR droop settings differ between the machines", "opts": ["Cable resistance difference", "Governor is faulty on one machine", "Unequal reactive (kVAR) load sharing \u2014 AVR droop settings differ between the machines", "Both generators have different rated voltages"], "exp": "Equal kW but different current means the machine with higher current is supplying more reactive power (kVAR) \u2014 it's more heavily excited. Adjust AVR droop trimmer on the over-excited machine to reduce reactive contribution until currents are equal.", "cat": "WP", "id": "T01_EX_131", "topic": "T01_Alternator"}, {"q": "What is 'droop' in the context of governor control?", "a": "Intentional slight reduction in speed/frequency as load (kW) increases \u2014 ensures stable kW sharing between parallel machines", "opts": ["The physical drooping of the governor spring", "Intentional slight reduction in speed/frequency as load (kW) increases \u2014 ensures stable kW sharing between parallel machines", "A fault condition where governor fails to respond", "Automatic shutdown when overloaded"], "exp": "Without droop, two governors would fight each other (hunt). Droop: if machine A takes more load, its speed drops slightly \u2192 governor reduces fuel slightly \u2192 load redistributes. Typical droop: 3\u20135%. Droop = (no-load speed \u2013 full-load speed) / rated speed \u00d7 100%.", "cat": "WP", "id": "T01_EX_132", "topic": "T01_Alternator"}, {"q": "One generator LOSES EXCITATION while running in parallel with another. What happens?", "a": "Machine runs as induction generator \u2014 absorbs reactive power from busbar, voltage drops, AVR tries to compensate, may lead to instability", "opts": ["Machine immediately trips on reverse power relay", "It safely continues running on reduced output", "Machine runs as induction generator \u2014 absorbs reactive power from busbar, voltage drops, AVR tries to compensate, may lead to instability", "Frequency collapses immediately"], "exp": "With lost excitation, the machine loses synchronism and operates as an induction generator. It now ABSORBS reactive power (instead of supplying). This pulls busbar voltage down. Loss-of-excitation relay (or under-voltage relay) should detect and trip. Risk: if not tripped, can cause voltage collapse.", "cat": "WP", "id": "T01_EX_133", "topic": "T01_Alternator"}, {"q": "What does the DIFFERENTIAL PROTECTION RELAY do on an alternator?", "a": "Compares current entering and leaving the winding \u2014 any difference indicates an internal fault", "opts": ["Compares voltage of two generators before paralleling", "Compares current entering and leaving the winding \u2014 any difference indicates an internal fault", "Detects frequency differences during synchronisation", "Monitors winding temperature balance"], "exp": "Differential protection: current transformers at both ends of stator winding compare ingoing vs outgoing current. Normally identical. Internal fault (turn-to-turn, phase-to-earth within winding) causes an imbalance \u2192 relay trips instantaneously. Highly sensitive \u2014 fastest protection for internal faults.", "cat": "PR", "id": "T01_EX_134", "topic": "T01_Alternator"}, {"q": "What is the setting for the REVERSE POWER RELAY on a marine alternator?", "a": "Trips at 5\u201310% of rated kW in reverse direction", "opts": ["Trips at 50% of rated kW", "Trips at any detectable reverse current", "Trips at 5\u201310% of rated kW in reverse direction", "Trips at 100% reverse power \u2014 only for severe motoring"], "exp": "Reverse power relay is set at 5\u201310% of rated kW. This is sensitive enough to detect motoring (prime mover failure) but insensitive enough to avoid nuisance trips during normal load fluctuations. Very large generators may have settings as low as 2\u20133%.", "cat": "PR", "id": "T01_EX_135", "topic": "T01_Alternator"}, {"q": "What is the function of the PREFERENTIAL TRIP relay?", "a": "Automatically sheds non-essential loads in stages when generator is persistently overloaded \u2014 before tripping the generator", "opts": ["Instantly disconnects the most important loads", "Automatically sheds non-essential loads in stages when generator is persistently overloaded \u2014 before tripping the generator", "Trips the generator if voltage is too high", "Prevents any additional loads from connecting"], "exp": "Preferential trip protects the generator from overload without blacking out the ship. It sheds non-essential services (galley, HVAC, etc.) in timed stages while keeping essential loads (navigation, steering, safety systems) running. Much better than total blackout.", "cat": "PR", "id": "T01_EX_136", "topic": "T01_Alternator"}, {"q": "What is a DASHPOT and why is it used with the preferential trip relay?", "a": "A pneumatic/hydraulic time-delay device \u2014 introduces time delay before shedding, allowing transient overloads to pass without unnecessary tripping", "opts": ["An oil reservoir for generator bearing lubrication", "A pneumatic/hydraulic time-delay device \u2014 introduces time delay before shedding, allowing transient overloads to pass without unnecessary tripping", "A capacitor that stores energy for instantaneous relay operation", "A mechanical brake on the generator shaft"], "exp": "The dashpot provides a settable time delay (typically 5\u201330 seconds). Without it, starting a large motor would trigger immediate load shedding. The dashpot allows the transient overload to pass. If overload persists beyond the delay \u2192 load is shed.", "cat": "PR", "id": "T01_EX_137", "topic": "T01_Alternator"}, {"q": "What bearing temperature values trigger ALARM and TRIP on a marine alternator?", "a": "Alarm at approximately 80\u00b0C, Trip at approximately 95\u00b0C", "opts": ["Alarm 60\u00b0C, Trip 70\u00b0C", "Alarm 80\u00b0C, Trip 150\u00b0C", "Alarm at approximately 80\u00b0C, Trip at approximately 95\u00b0C", "Alarm 100\u00b0C, Trip 120\u00b0C"], "exp": "PT100 resistance temperature detectors in bearings: ~80\u00b0C alarm gives warning to investigate (inadequate lubrication, overload). ~95\u00b0C trip prevents bearing seizure/damage. Different ships may have slightly different values \u2014 always check ship's documentation.", "cat": "PR", "id": "T01_EX_138", "topic": "T01_Alternator"}, {"q": "What is the purpose of the THERMISTOR protection in an alternator stator?", "a": "Embedded in stator winding \u2014 trips if winding temperature exceeds Class F insulation limit (155\u00b0C)", "opts": ["Monitors ambient temperature in the engine room", "Embedded in stator winding \u2014 trips if winding temperature exceeds Class F insulation limit (155\u00b0C)", "Controls AVR output based on temperature", "Measures coolant temperature of the prime mover"], "exp": "Thermistors (PTC type) are embedded directly in stator winding slots during manufacturing. Class F insulation is rated to 155\u00b0C. Trip prevents insulation degradation and winding burnout. The thermistor resistance increases sharply at the trip temperature, triggering the relay circuit.", "cat": "PR", "id": "T01_EX_139", "topic": "T01_Alternator"}, {"q": "What is EARTH FAULT PROTECTION on an alternator, and what percentage of stator is protected?", "a": "Detects stator winding earth faults \u2014 typically 95% stator earth fault protection (5% nearest neutral is unprotected)", "opts": ["100% of stator is protected in all modern ships", "Only the terminal box connections are protected", "Detects stator winding earth faults \u2014 typically 95% stator earth fault protection (5% nearest neutral is unprotected)", "Earth fault protection is optional on marine alternators"], "exp": "95% protection is standard \u2014 the 5% nearest the star-point (neutral) has insufficient voltage to drive the detection relay. For 100% protection, a low-frequency injection method is used. Earth fault protection prevents single earth fault from developing into a phase-to-phase fault.", "cat": "PR", "id": "T01_EX_140", "topic": "T01_Alternator"}, {"q": "What does OVER-VOLTAGE RELAY protect against, and at what setting does it trip?", "a": "Protects insulation from damage \u2014 trips at approximately 110% of rated voltage", "opts": ["Protects against reverse power \u2014 trips at 50% over", "Protects insulation from damage \u2014 trips at approximately 110% of rated voltage", "Only operates during synchronisation \u2014 no trip setting", "Trips at 125% for continuous protection"], "exp": "Over-voltage damages insulation and connected equipment. AVR should prevent this, but if AVR fails (thyristor short circuit), voltage can shoot up. Over-voltage relay trips at ~110% rated voltage. Response time is typically definite-time (short delay to avoid nuisance trips on transients).", "cat": "PR", "id": "T01_EX_141", "topic": "T01_Alternator"}, {"q": "What is the minimum acceptable IR (Insulation Resistance) value for a marine alternator winding?", "a": "Minimum 1 M\u03a9; Polarisation Index (PI) > 2 indicates good insulation", "opts": ["Minimum 10 k\u03a9 is acceptable for marine service", "Minimum 100 M\u03a9 for running machines", "Minimum 1 M\u03a9; Polarisation Index (PI) > 2 indicates good insulation", "Any reading above zero is acceptable"], "exp": "1 M\u03a9 is the absolute minimum. In practice, a good dry winding reads hundreds of M\u03a9. PI (10-min reading / 1-min reading) > 2 = good insulation condition. PI 1\u20132 = fair. PI <1 = dangerous \u2014 do not run. Always discharge winding after meggering.", "cat": "MT", "id": "T01_EX_142", "topic": "T01_Alternator"}, {"q": "What voltage megger is used for a 440V alternator IR test?", "a": "500V DC megger", "opts": ["250V DC \u2014 to avoid damaging the insulation", "1000V DC \u2014 for thorough testing", "5000V DC \u2014 to match starting voltage", "500V DC megger"], "exp": "Rule of thumb: megger voltage should be approximately equal to rated voltage + 250V, or use standard values: 500V for low voltage equipment (<1000V), 1000V for medium voltage, 5000V for high voltage (>11kV). 500V for 440V alternator is standard.", "cat": "MT", "id": "T01_EX_143", "topic": "T01_Alternator"}, {"q": "What must be done to the winding AFTER performing an IR test?", "a": "Discharge the winding by connecting it to earth via a resistor \u2014 capacitive charge can cause electric shock", "opts": ["Re-connect to AVR immediately to restore normal operation", "Discharge the winding by connecting it to earth via a resistor \u2014 capacitive charge can cause electric shock", "Measure AC voltage at terminals to confirm discharge", "No action needed \u2014 megger automatically discharges"], "exp": "Megger charges the winding capacitance to DC test voltage (500V or more). This charge is retained after removing the megger. Short-circuiting directly causes arc \u2014 use a high resistance first, then earth. Time constant depends on winding capacitance. Always discharge before touching.", "cat": "MT", "id": "T01_EX_144", "topic": "T01_Alternator"}, {"q": "How do you maintain alternator insulation during cold region drydock?", "a": "Use anti-condensation heaters to maintain winding temperature above dewpoint; megger frequently to monitor IR", "opts": ["Keep the machine running at full load throughout drydock", "Wrap the machine in plastic sheeting to exclude moisture", "Use anti-condensation heaters to maintain winding temperature above dewpoint; megger frequently to monitor IR", "Apply oil to windings to repel moisture"], "exp": "Cold air holds less moisture, but when it warms up near the winding, condensation forms. Winding heaters keep the winding slightly above ambient \u2014 prevents dew point from being reached. If IR is already low, use gentle heating to dry out before switching on. Never megger a wet winding.", "cat": "WP", "id": "T01_EX_145", "topic": "T01_Alternator"}, {"q": "After receiving a rewound alternator from shore \u2014 what checks must you do before commissioning?", "a": "Visual check, IR test, phase rotation check, no-load voltage check, then gradual load test", "opts": ["Just run at full load for 30 minutes", "Only check voltage output", "Visual check, IR test, phase rotation check, no-load voltage check, then gradual load test", "Send it back for further testing \u2014 never trust shore rewind"], "exp": "Systematic commissioning: (1) Visual \u2014 winding quality, varnish, connections. (2) IR test \u2014 all phases to earth. (3) Phase rotation \u2014 must match ship's system. (4) No-load run \u2014 check voltage, frequency, noise, vibration. (5) Parallel with running generator \u2014 check load sharing. (6) Gradually apply load.", "cat": "MT", "id": "T01_EX_146", "topic": "T01_Alternator"}, {"q": "What checks are included in DAILY running checks on an alternator?", "a": "Check voltage, current, frequency, power factor, bearing temperatures, vibration, abnormal noise", "opts": ["Megger test every day", "Check voltage, current, frequency, power factor, bearing temperatures, vibration, abnormal noise", "Strip and inspect bearings daily", "Perform IR test and AVR calibration daily"], "exp": "Daily checks are visual/instrument \u2014 no shutdown needed. Look at: switchboard meters (V, A, Hz, PF, kW). Listen for: abnormal noise, vibration. Touch (briefly): check bearing housing temperature. Log all readings. Any trend change warrants investigation.", "cat": "WP", "id": "T01_EX_147", "topic": "T01_Alternator"}, {"q": "What is the 'air gap' in an alternator?", "a": "The clearance between the rotor pole face and the inner surface of the stator bore", "opts": ["The space between stator teeth for ventilation", "The clearance between the rotor pole face and the inner surface of the stator bore", "The gap in the rectifier circuit for voltage regulation", "The distance between two phase windings in the stator"], "exp": "The air gap is critical: too small \u2192 rotor rubs on stator (mechanical damage). Too large \u2192 increased reluctance \u2192 less efficient, lower output for same excitation. Uneven air gap \u2192 unbalanced magnetic pull \u2192 vibration and bearing wear.", "cat": "AG", "id": "T01_EX_148", "topic": "T01_Alternator"}, {"q": "What happens if the air gap is UNEVEN around the circumference?", "a": "Unbalanced magnetic pull causes rotor vibration, bearing wear, and in severe cases rotor-stator contact", "opts": ["Nothing \u2014 air gap unevenness is normal and acceptable", "Voltage output becomes unbalanced between phases", "Unbalanced magnetic pull causes rotor vibration, bearing wear, and in severe cases rotor-stator contact", "Only affects power factor, no mechanical effects"], "exp": "Uneven air gap means the magnetic field is stronger where the gap is smaller. This creates a net radial force pulling the rotor towards the smaller gap side (UMP \u2014 Unbalanced Magnetic Pull). This is self-aggravating \u2014 as rotor moves closer, force increases. Can lead to bearing failure or rotor/stator contact.", "cat": "AG", "id": "T01_EX_149", "topic": "T01_Alternator"}, {"q": "At what speed does the overspeed trip activate on a marine auxiliary diesel-alternator set?", "a": "110\u2013115% of rated speed", "opts": ["90% of rated speed", "100% rated speed \u2014 at setpoint", "110\u2013115% of rated speed", "150% \u2014 only for extreme emergency"], "exp": "Overspeed trip is set to activate at 110\u2013115% of rated speed (not 100% \u2014 that would interfere with normal speed variations). For a 1500 RPM generator, trip activates at 1650\u20131725 RPM. It's a mechanical or electronic trip that cuts fuel supply.", "cat": "OS", "id": "T01_EX_150", "topic": "T01_Alternator"}, {"q": "How do you test the overspeed trip of a marine auxiliary engine?", "a": "Run off-load with ACB open, gradually increase governor speed until trip activates; note trip RPM and compare to specification", "opts": ["Only check by monitoring the trip in emergency \u2014 never test deliberately", "Apply full rated load then suddenly remove it", "Run off-load with ACB open, gradually increase governor speed until trip activates; note trip RPM and compare to specification", "Simulate by injecting a signal into the electronic governor"], "exp": "Method 1 (actual): ACB open, increase fuel slowly until trip fires. Verify RPM at trip. Method 2 (simulated): Electronic engines \u2014 simulate via test function. Record: date, trip speed, result in engine log. Frequency: annually or at drydock as per class/SOLAS requirement.", "cat": "OS", "id": "T01_EX_151", "topic": "T01_Alternator"}, {"q": "What is the purpose of a blackout test?", "a": "Verify emergency generator auto-starts and supplies essential loads within 45 seconds", "opts": ["Test the fire detection system under power failure", "Verify emergency generator auto-starts and supplies essential loads within 45 seconds", "Check battery capacity for emergency lighting only", "Test the preferential trip relay sequence"], "exp": "SOLAS requires emergency generator to start automatically and supply essential services within 45 seconds of main power failure. The blackout test verifies this. Essential loads: emergency lighting, navigation lights, steering gear, fire pump, communications.", "cat": "BT", "id": "T01_EX_152", "topic": "T01_Alternator"}, {"q": "During a blackout test, what is the correct sequence of actions for the ETO?", "a": "Brief staff, inform bridge, verify emergency DG ready, trip main ACBs, time DG start, verify essential loads, restore main power, reconnect in sequence", "opts": ["Simply trip the main breaker and observe", "Brief staff, inform bridge, verify emergency DG ready, trip main ACBs, time DG start, verify essential loads, restore main power, reconnect in sequence", "Only the chief engineer performs blackout test \u2014 ETO observes", "Run emergency generator for 10 minutes without tripping main power"], "exp": "Safety first: always inform bridge (safe navigational situation), brief all staff (machinery spaces and bridge watchkeepers). Verify emergency DG has fuel, lube oil, coolant. Trip ACBs. Start stopwatch \u2014 DG must start and supply within 45 sec. Record results in log.", "cat": "BT", "id": "T01_EX_153", "topic": "T01_Alternator"}, {"q": "After a blackout, in what ORDER should loads be restored when bringing main generator back on line?", "a": "Navigation/steering first, then essential safety services, then machinery systems, lastly non-essential services", "opts": ["Restore all loads simultaneously to speed up recovery", "Largest loads first to test generator capacity", "Navigation/steering first, then essential safety services, then machinery systems, lastly non-essential services", "Non-essential loads first \u2014 leave critical loads on emergency generator longer"], "exp": "Sequence matters to avoid overloading the generator during recovery. Priority: (1) Navigation, bridge equipment, steering. (2) Fire detection, bilge pumps, safety systems. (3) Essential machinery (fuel pumps, cooling pumps). (4) Accommodation, galley, HVAC last. Introduce loads with time delays between groups.", "cat": "BT", "id": "T01_EX_154", "topic": "T01_Alternator"}, {"q": "Why is the main generator NOT placed at the bottom of the engine room (tank top level)?", "a": "Flooding risk, excessive vibration, poor maintenance access, inadequate cooling \u2014 all prevented by elevated placement", "opts": ["It would be too cold at tank top level", "SOLAS specifically prohibits bottom placement for weight distribution", "Flooding risk, excessive vibration, poor maintenance access, inadequate cooling \u2014 all prevented by elevated placement", "The prime mover would overheat if placed at tank top"], "exp": "(1) Tank top floods first \u2014 submerged generator = complete power loss. (2) Tank top vibration from ME + shaft is highest. (3) Overhead crane access needed for major maintenance. (4) Better forced ventilation at upper levels. SOLAS II-1/Reg 40 mandates flood protection for main power sources.", "cat": "SOL", "id": "T01_EX_155", "topic": "T01_Alternator"}, {"q": "Where MUST the emergency generator be located according to SOLAS?", "a": "Above the bulkhead deck, OUTSIDE the main machinery space, in a separate compartment", "opts": ["In a waterproof enclosure at tank top level", "Adjacent to the main switchboard in the ECR", "Above the bulkhead deck, OUTSIDE the main machinery space, in a separate compartment", "Any location that can be remotely started from bridge"], "exp": "SOLAS Ch. II-1 Reg 42/43: Emergency generator must be (1) Above the bulkhead deck (so flooding of machinery space doesn't affect it). (2) Entirely outside the machinery space (so fire or flooding in ER doesn't disable it). Purpose: independent survival in any casualty.", "cat": "SOL", "id": "T01_EX_156", "topic": "T01_Alternator"}, {"q": "A 440V motor receives only 280V. What happens to its torque?", "a": "Torque reduces proportional to voltage squared: (280/440)\u00b2 \u2248 0.40 \u2014 only ~40% of rated torque", "opts": ["Torque reduces proportionally to voltage: (280/440) = 63%", "Torque increases as motor tries harder", "Torque reduces proportional to voltage squared: (280/440)\u00b2 \u2248 0.40 \u2014 only ~40% of rated torque", "No change in torque \u2014 only speed changes"], "exp": "Torque \u221d V\u00b2. This is because torque depends on both the field strength and armature current \u2014 both reduced at lower voltage. With only 40% torque, an under loaded motor may run slowly; a normal-load motor will stall. This is a critical design consideration for motor starting.", "cat": "FT", "id": "T01_EX_157", "topic": "T01_Alternator"}, {"q": "What happens to the current drawn by a motor running on under-voltage?", "a": "Current rises 2\u20133\u00d7 rated value to compensate for reduced torque \u2014 causes severe overheating", "opts": ["Current reduces in proportion to voltage", "Current stays constant \u2014 it's load-dependent only", "Current rises 2\u20133\u00d7 rated value to compensate for reduced torque \u2014 causes severe overheating", "Current fluctuates randomly with voltage changes"], "exp": "Under voltage \u2192 reduced air-gap flux \u2192 reduced back-EMF \u2192 motor draws more current to maintain torque. If motor is carrying load and voltage drops significantly, it may fail to maintain speed, slip increases dramatically, current rockets up, and thermal protection (overload relay) should trip it.", "cat": "WP", "id": "T01_EX_158", "topic": "T01_Alternator"}, {"q": "What causes pitting marks on alternator slip rings?", "a": "High current sparking from worn, misaligned or incorrect grade brushes; contamination on ring surface", "opts": ["Excessive lubrication causing surface erosion", "High current sparking from worn, misaligned or incorrect grade brushes; contamination on ring surface", "Normal wear \u2014 pitting is expected and acceptable", "Overvoltage from AVR malfunction"], "exp": "Causes: (1) Brush pressure incorrect \u2014 too low allows bouncing (sparking), too high causes excessive wear. (2) Wrong brush grade \u2014 not matched to ring material. (3) Contamination \u2014 oil, water, carbon dust. (4) Mechanical misalignment \u2014 eccentric running. All cause arcing \u2192 pitting.", "cat": "SR", "id": "T01_EX_159", "topic": "T01_Alternator"}, {"q": "What is the correct brush pressure range for slip ring brushes?", "a": "Typically 150\u2013200 g/cm\u00b2", "opts": ["As tight as possible to ensure good contact", "10\u201350 g/cm\u00b2", "Typically 150\u2013200 g/cm\u00b2", "500\u2013800 g/cm\u00b2 for high current applications"], "exp": "Too low pressure: brush bounces \u2192 arcing \u2192 pitting \u2192 more resistance \u2192 more heat \u2192 brush burns. Too high pressure: excessive friction \u2192 overheating \u2192 rapid brush wear \u2192 brush dust contamination. 150\u2013200 g/cm\u00b2 is the standard \u2014 check with a spring balance gauge.", "cat": "SR", "id": "T01_EX_160", "topic": "T01_Alternator"}, {"q": "How do you correct slip ring pitting while the machine is running?", "a": "Use fine emery cloth held in an insulated holder to lightly dress the surface \u2014 reduce load to minimum first", "opts": ["Machine must always be stopped before any slip ring work", "Remove slip ring cover and polish by hand", "Use fine emery cloth held in an insulated holder to lightly dress the surface \u2014 reduce load to minimum first", "Apply conductive paste to fill in the pits"], "exp": "Minor pitting can be dressed in-service: reduce load, use fine emery cloth on an insulated stick/holder (NEVER bare hands near live slip rings). This smooths the surface, improving contact. Check afterward: smooth bright contact surface, sparking subsided. Severe pitting: machine lathe in drydock.", "cat": "SR", "id": "T01_EX_161", "topic": "T01_Alternator"}, {"q": "What actually happens when an ACB is closed on a generator that is NOT running?", "a": "Running generator back-feeds through ACB \u2014 idle machine runs as induction motor (motoring), reverse power relay trips ACB", "opts": ["Nothing happens \u2014 no circuit without running generator", "Running generator back-feeds through ACB \u2014 idle machine runs as induction motor (motoring), reverse power relay trips ACB", "Both generators trip on overcurrent simultaneously", "The idle generator starts automatically"], "exp": "This is a classic exam trick question. Non-running generator has no voltage. When ACB closes, it's just connecting a dead winding to the live busbar. The live busbar now drives current through the idle stator winding, causing it to rotate (induction motor effect). Reverse power relay detects reverse power flow and trips the ACB \u2014 if it works correctly.", "cat": "WP", "id": "T01_EX_162", "topic": "T01_Alternator"}, {"q": "Which protection relay prevents an alternator from 'motoring' when connected to the busbar?", "a": "Reverse power relay", "opts": ["Differential relay", "Under-voltage relay", "Reverse power relay", "Over-current relay"], "exp": "Reverse power relay monitors the direction of real power (kW) flow. Normal operation: power flows FROM generator TO busbar. Motoring: power flows FROM busbar TO generator. When reverse power exceeds setpoint (5\u201310% rated) for the set time, relay trips ACB.", "cat": "PR", "id": "T01_EX_163", "topic": "T01_Alternator"}, {"q": "What is the Polarisation Index (PI) and what does PI > 2 indicate?", "a": "PI = IR at 10 minutes \u00f7 IR at 1 minute; PI > 2 = good dry insulation in good condition", "opts": ["PI measures the alternator's power factor improvement", "PI = maximum current \u00f7 rated current; PI > 2 means overload capacity", "PI = IR at 10 minutes \u00f7 IR at 1 minute; PI > 2 = good dry insulation in good condition", "PI is the ratio of bearing temperature to winding temperature"], "exp": "Polarisation Index distinguishes good dry insulation (resistance keeps rising over time) from contaminated/wet insulation (resistance stays constant or drops). PI > 2 = excellent. PI 1\u20132 = fair (investigate). PI < 1 = dangerous \u2014 do not energise. Wet windings show very low PI.", "cat": "MT", "id": "T01_EX_164", "topic": "T01_Alternator"}, {"q": "Why is an alternator rated with Class F insulation significant for temperature monitoring?", "a": "Class F insulation is rated to 155\u00b0C \u2014 thermostat/thermistor trip settings are calibrated to this limit", "opts": ["Class F means the alternator can only run in F-rated (flammable) zones", "Class F insulation is rated to 155\u00b0C \u2014 thermostat/thermistor trip settings are calibrated to this limit", "All marine alternators use Class B \u2014 Class F is only for shore installations", "Class F certification is required by MARPOL"], "exp": "Insulation class defines maximum continuous temperature: Class B=130\u00b0C, Class F=155\u00b0C, Class H=180\u00b0C. Marine alternators use Class F. Thermistor trip is set just below 155\u00b0C (typically 145\u2013150\u00b0C to give margin). Running above this degrades insulation life exponentially.", "cat": "WP", "id": "T01_EX_165", "topic": "T01_Alternator"}, {"q": "During a survey, the surveyor asks you to test the overcurrent relay. How do you perform this?", "a": "Secondary injection test: rack ACB to TEST position, inject calculated current into CT secondary terminals, verify relay trips at set value", "opts": ["Overload the generator to 110% and observe relay", "Short the generator terminals briefly and measure response time", "Secondary injection test: rack ACB to TEST position, inject calculated current into CT secondary terminals, verify relay trips at set value", "Simulate fault using an insulation tester connected to phase terminals"], "exp": "Secondary injection: don't need to actually overload the machine. Disconnect CT secondary. Inject a measured AC current (using test set) that corresponds to the relay's trip setting when scaled by CT ratio. Time the relay trip. Record: set value, actual trip current, trip time. Compare to manufacturer spec.", "cat": "PR", "id": "T01_EX_166", "topic": "T01_Alternator"}, {"q": "What is the minimum time for the emergency generator to start and supply essential loads per SOLAS?", "a": "45 seconds", "opts": ["5 minutes", "2 minutes", "45 seconds", "10 minutes"], "exp": "SOLAS Ch. II-1 Reg 43: Emergency generator must start automatically and supply at least the emergency loads within 45 seconds of main power failure. This is why emergency generators are kept warm (pre-heaters) and tested regularly to ensure reliable starting.", "cat": "BT", "id": "T01_EX_167", "topic": "T01_Alternator"}, {"q": "What is the advantage of a brushless alternator over a conventionally excited alternator for UMS ships?", "a": "No brushes means no carbon dust, no brush inspection needed, no sparking \u2014 suitable for unattended operation", "opts": ["Brushless alternators produce higher voltage", "No brushes means no carbon dust, no brush inspection needed, no sparking \u2014 suitable for unattended operation", "Brushless alternators always have higher efficiency", "They can operate on lower frequency for UMS operation"], "exp": "UMS (Unattended Machinery Space) ships need equipment that can run reliably without continuous monitoring. Brushless: no brush replacement, no slip ring pitting, no carbon tracking, no brush gear sparking (safer in gas-risk areas). Much lower maintenance requirement \u2014 ideal for UMS.", "cat": "BL", "id": "T01_EX_168", "topic": "T01_Alternator"}, {"q": "What checks should be done when receiving a 'no voltage' complaint on a running alternator \u2014 in order?", "a": "1. Check voltmeter accuracy, 2. Check frequency/speed, 3. Try AVR trimmer, 4. Check PMG output, 5. Flash if needed", "opts": ["Immediately shut down and dismantle", "Only check AVR first", "1. Check voltmeter accuracy, 2. Check frequency/speed, 3. Try AVR trimmer, 4. Check PMG output, 5. Flash if needed", "Run at half load and restart from scratch"], "exp": "Systematic: (1) Is voltmeter working? (check with handheld). (2) Is generator at speed? (check tacho). (3) Is AVR supplying field? (check AVR output). (4) Is PMG generating? (check PMG output). (5) Residual magnetism \u2014 try flashing. (6) Field winding open circuit \u2014 resistance check. (7) Rotating diodes \u2014 stroboscope.", "cat": "WP", "id": "T01_EX_169", "topic": "T01_Alternator"}, {"cat": "WP", "q": "State Faraday's Law of electromagnetic induction as it applies to an alternator.", "a": "EMF is induced in a conductor proportional to the rate of change of magnetic flux linkage", "opts": ["EMF is constant when flux is constant", "EMF is induced in a conductor proportional to the rate of change of magnetic flux linkage", "EMF depends only on conductor resistance", "EMF is produced by the static field alone"], "exp": "Faraday's Law: e = -N(d\u03a6/dt). In an alternator, the rotating rotor field cuts stator conductors \u2014 rate of flux change induces the EMF. The negative sign (Lenz's Law) means induced EMF opposes the change.", "id": "T01_NEW_001", "topic": "T01_Alternator"}, {"cat": "WP", "q": "A 4-pole alternator runs at 1500 RPM. What is its output frequency?", "a": "50 Hz", "opts": ["25 Hz", "60 Hz", "50 Hz", "100 Hz"], "exp": "f = (N \u00d7 P) / 120 = (1500 \u00d7 4) / 120 = 50 Hz. Standard shore frequency in most countries (Europe, Asia). US/Americas use 60 Hz \u2192 requires 1800 RPM for 4 poles.", "id": "T01_NEW_002", "topic": "T01_Alternator"}, {"cat": "WP", "q": "A 4-pole alternator must produce 60 Hz. What RPM is required?", "a": "1800 RPM", "opts": ["1500 RPM", "3000 RPM", "1800 RPM", "900 RPM"], "exp": "N = (f \u00d7 120) / P = (60 \u00d7 120) / 4 = 1800 RPM. This is the standard speed for diesel-alternator sets on ships serving US/Canadian ports or built to USCG standards.", "id": "T01_NEW_003", "topic": "T01_Alternator"}, {"cat": "WP", "q": "A 6-pole alternator runs at 1000 RPM. What frequency does it produce?", "a": "50 Hz", "opts": ["30 Hz", "50 Hz", "60 Hz", "100 Hz"], "exp": "f = (1000 \u00d7 6) / 120 = 50 Hz. More poles allow lower shaft speed for the same frequency \u2014 useful for low-speed prime movers. Larger diameter rotor needed.", "id": "T01_NEW_004", "topic": "T01_Alternator"}, {"cat": "WP", "q": "Why is a marine alternator rated in kVA rather than kW?", "a": "Heating depends on current (which determines kVA), not on power factor \u2014 so kVA is the true capacity rating", "opts": ["kVA is always a larger number than kW", "kW rating is only for DC machines", "Heating depends on current (which determines kVA), not on power factor \u2014 so kVA is the true capacity rating", "SOLAS mandates kVA rating for all AC machines"], "exp": "Copper losses I\u00b2R cause winding heating \u2014 depend only on current magnitude. A 100 kVA machine at 0.5 PF delivers 50 kW but carries full rated current \u2192 full rated heating. At 1.0 PF it delivers 100 kW with same current \u2192 same heating. The machine doesn't 'know' the PF of its load.", "id": "T01_NEW_005", "topic": "T01_Alternator"}, {"cat": "WP", "q": "What is the relationship between frequency, number of pole pairs, and speed?", "a": "f = n \u00d7 P/2 (where n = rev/sec, P = total poles) or f = N \u00d7 P / 120 (N in RPM)", "opts": ["f = N / P \u00d7 60", "f = n \u00d7 P/2 (where n = rev/sec, P = total poles) or f = N \u00d7 P / 120 (N in RPM)", "f = V / I \u00d7 P", "f = RPM / 60"], "exp": "The formula f = NP/120 uses RPM. Equivalently f = nP/2 where n is rev/second and P is total pole count. Each rotation of a P-pole rotor completes P/2 full cycles. Governor maintains constant N \u2192 constant f.", "id": "T01_NEW_006", "topic": "T01_Alternator"}, {"cat": "WP", "q": "In a marine alternator, why is AC output taken from the stator and not the rotor?", "a": "Stator is stationary \u2014 no slip rings needed to take output; rotor only carries DC field (low current)", "opts": ["Rotor windings cannot carry AC current", "Stator is stationary \u2014 no slip rings needed to take output; rotor only carries DC field (low current)", "Stator produces higher voltage", "Rotor output would have incorrect frequency"], "exp": "Taking AC output from a rotating part would require slip rings rated for full output current (hundreds of amps). The stationary stator allows direct cable connection. The DC field current on the rotor is much smaller \u2014 manageable via slip rings (in conventional machines) or eliminated entirely (brushless).", "id": "T01_NEW_007", "topic": "T01_Alternator"}, {"cat": "WP", "q": "What is the synchronous speed of a 2-pole alternator for 50 Hz output?", "a": "3000 RPM", "opts": ["1500 RPM", "1800 RPM", "3000 RPM", "6000 RPM"], "exp": "N = (f \u00d7 120) / P = (50 \u00d7 120) / 2 = 3000 RPM. Two-pole machines run very fast \u2014 typically turbo-alternators on steam/gas turbine ships. Cylindrical (non-salient) rotor construction used for structural integrity at high speed.", "id": "T01_NEW_008", "topic": "T01_Alternator"}, {"cat": "EX", "q": "Name the THREE types of excitation systems used on marine alternators.", "a": "Separately excited, Self-excited (shunt), Brushless (PMG + exciter + rotating rectifiers)", "opts": ["AC excited, DC excited, Static excited", "Separately excited, Self-excited (shunt), Brushless (PMG + exciter + rotating rectifiers)", "Battery excited, Shore excited, Self-excited", "Permanent magnet, Thyristor controlled, Transformer excited"], "exp": "(1) Separately excited: external DC source via slip rings. (2) Self-excited shunt: output feeds back via rectifier to field. (3) Brushless: PMG \u2192 AVR \u2192 exciter stator \u2192 exciter rotor \u2192 rotating diodes \u2192 main field. Modern marine = brushless.", "id": "T01_NEW_009", "topic": "T01_Alternator"}, {"cat": "EX", "q": "What is the main disadvantage of a separately excited alternator?", "a": "Requires slip rings and brushes for field supply \u2014 maintenance-intensive, prone to sparking", "opts": ["Cannot produce stable voltage", "Requires slip rings and brushes for field supply \u2014 maintenance-intensive, prone to sparking", "Output frequency varies with load", "Cannot be used on ships above 5000 GRT"], "exp": "Slip rings and brushes need regular maintenance: brush replacement, slip ring cleaning/polishing, pressure checking. In marine environment \u2014 humidity, vibration, salt air \u2014 brushes wear faster and can cause tracking/arcing. Brushless eliminates this entirely.", "id": "T01_NEW_010", "topic": "T01_Alternator"}, {"cat": "EX", "q": "In a self-excited shunt alternator, what happens if you briefly disconnect the field?", "a": "Voltage collapses completely \u2014 no external source to restore it without residual magnetism or flashing", "opts": ["Voltage stays at 90% of rated", "Voltage collapses completely \u2014 no external source to restore it without residual magnetism or flashing", "Overcurrent relay trips", "Frequency drops proportionally"], "exp": "Self-excitation relies on the bootstrap cycle: residual magnetism \u2192 small voltage \u2192 field current \u2192 more voltage. Interrupt this cycle (field disconnect) and voltage collapses. PMG-based brushless machines are immune \u2014 PMG provides stable power to AVR regardless of main output voltage.", "id": "T01_NEW_011", "topic": "T01_Alternator"}, {"cat": "EX", "q": "What voltage does the PMG typically output, and what is it used for?", "a": "100\u2013200V AC, used solely to power the AVR \u2014 completely independent of main alternator output", "opts": ["440V AC \u2014 matches main busbar", "100\u2013200V AC, used solely to power the AVR \u2014 completely independent of main alternator output", "12V DC \u2014 directly feeds the field winding", "48V DC \u2014 powers the AVR and ship's DC systems"], "exp": "PMG output voltage and frequency vary with speed, but since it's used to power the AVR (which can handle varying input), this is acceptable. Critical feature: PMG output is unaffected by main alternator faults, AVR faults, or load disturbances \u2014 providing a truly independent supply.", "id": "T01_NEW_012", "topic": "T01_Alternator"}, {"cat": "EX", "q": "Can a brushless alternator self-excite if the PMG magnets demagnetise completely?", "a": "No \u2014 if PMG loses all magnetism, AVR has no supply and cannot excite the main field; machine won't build voltage", "opts": ["Yes \u2014 residual magnetism in main rotor will still build voltage", "No \u2014 if PMG loses all magnetism, AVR has no supply and cannot excite the main field; machine won't build voltage", "Yes \u2014 the self-excited bypass mode activates automatically", "No \u2014 but the battery charger provides backup excitation"], "exp": "In a brushless machine, the PMG is the sole supply to the AVR. If PMG permanent magnets lose their field (rare, but possible from severe shock or temperature), the AVR starves \u2192 no excitation \u2192 no output. Unlike a self-excited machine, there's no residual magnetism path to bootstrap. Machine must be workshop-repaired.", "id": "T01_NEW_013", "topic": "T01_Alternator"}, {"cat": "BL", "q": "List the THREE machines on the shaft of a brushless alternator system in correct order from drive end.", "a": "PMG \u2192 Main Exciter \u2192 Main Alternator (all on same shaft, driven by prime mover)", "opts": ["Main Alternator \u2192 Exciter \u2192 PMG", "Governor \u2192 PMG \u2192 Main Alternator", "PMG \u2192 Main Exciter \u2192 Main Alternator (all on same shaft, driven by prime mover)", "Exciter \u2192 PMG \u2192 Main Alternator"], "exp": "Drive end (prime mover) \u2192 PMG (permanent magnet generator, small) \u2192 Main Exciter (stator is fed by AVR; rotor generates 3-phase AC) \u2192 Main Alternator (rotor carries DC field from rotating rectifiers; stator gives 3-phase output). All on one shaft.", "id": "T01_NEW_014", "topic": "T01_Alternator"}, {"cat": "BL", "q": "What is the role of the exciter stator winding in a brushless alternator?", "a": "Carries DC field current from AVR \u2014 creates the magnetic field that the rotating exciter armature cuts", "opts": ["Carries the 3-phase AC output to the main switchboard", "Connects to the PMG to boost its output", "Carries DC field current from AVR \u2014 creates the magnetic field that the rotating exciter armature cuts", "Acts as the regulating winding for frequency control"], "exp": "The exciter is essentially a small DC-excited generator. Its stator (stationary) receives DC from the AVR. This creates a stationary magnetic field. The exciter rotor (rotating with shaft) cuts this field \u2192 generates 3-phase AC on the exciter rotor. This AC goes to rotating rectifiers on the shaft.", "id": "T01_NEW_015", "topic": "T01_Alternator"}, {"cat": "BL", "q": "Why are rotating rectifier diodes used instead of slip rings in a brushless alternator?", "a": "Rotating diodes eliminate physical sliding contact \u2014 no brushes, no sparking, no maintenance, suitable for UMS", "opts": ["Diodes produce higher voltage than slip rings", "Rotating diodes eliminate physical sliding contact \u2014 no brushes, no sparking, no maintenance, suitable for UMS", "Slip rings cannot handle AC current", "Diodes regulate the field current automatically"], "exp": "The exciter rotor generates 3-phase AC. To get DC into the main field winding (also on the rotor), you need rectification. Mounting diodes on the shaft means they rotate with the rotor \u2014 converting AC to DC right there on the shaft, without any need for electrical contact between stationary and rotating parts.", "id": "T01_NEW_016", "topic": "T01_Alternator"}, {"cat": "BL", "q": "What protection component is fitted across the rotating rectifier diode bank?", "a": "Zener diode suppressor \u2014 clamps transient overvoltages that could destroy the rectifier diodes", "opts": ["A fuse bank rated at 3\u00d7 diode current", "A varistor (MOV) for surge absorption", "Zener diode suppressor \u2014 clamps transient overvoltages that could destroy the rectifier diodes", "A thermistor to limit current during starting"], "exp": "Transient voltages occur in the field circuit during load changes or faults. Zener diodes across the diode bank clamp these spikes \u2014 they conduct when voltage exceeds their breakdown voltage, dissipating the energy. Without this protection, transients could instantly destroy the rectifier diodes.", "id": "T01_NEW_017", "topic": "T01_Alternator"}, {"cat": "BL", "q": "During a stroboscope inspection of rotating diodes, what specifically indicates a failed (open circuit) diode?", "a": "Discolouration (burn marks), pitting on the diode body, or cracks on the diode casing", "opts": ["The diode appears to spin faster than the others", "Discolouration (burn marks), pitting on the diode body, or cracks on the diode casing", "All diodes glow red under the stroboscope", "The diode appears to be at a different angle than neighbours"], "exp": "A failed diode that has burnt shows heat discolouration \u2014 typically brown/black marks. Pitting indicates arcing. Cracks mean mechanical failure. The stroboscope freezes apparent rotation so these visual defects are visible. An open circuit diode also shows up as: unbalanced 3-phase output voltage + ripple on output.", "id": "T01_NEW_018", "topic": "T01_Alternator"}, {"cat": "BL", "q": "A brushless alternator has 6 rotating diodes (3 positive, 3 negative). One negative diode goes open. What is the electrical effect?", "a": "One phase of exciter AC is not rectified \u2192 ripple in field current \u2192 pulsating terminal voltage", "opts": ["Complete loss of excitation \u2014 machine de-excites immediately", "Machine runs normally \u2014 remaining 5 diodes compensate", "One phase of exciter AC is not rectified \u2192 ripple in field current \u2192 pulsating terminal voltage", "Frequency drops by 1/6"], "exp": "The 3-phase bridge rectifier loses one leg. The remaining 5 diodes still rectify 2 of the 3 phases (partially). The unrectified phase component creates an AC ripple superimposed on the DC field. Result: 'hunting' or pulsating terminal voltage \u2014 typically 15-20% drop with visible fluctuation.", "id": "T01_NEW_019", "topic": "T01_Alternator"}, {"cat": "BL", "q": "How would you confirm a suspected rotating diode failure WITHOUT stopping the alternator?", "a": "Use stroboscope to freeze rotor visually (inspect diodes); measure output voltage imbalance; check for AC ripple on field supply", "opts": ["Disconnect the PMG and see if voltage changes", "Use stroboscope to freeze rotor visually (inspect diodes); measure output voltage imbalance; check for AC ripple on field supply", "Open the terminal box and probe with voltmeter", "Increase load to 100% and measure current balance"], "exp": "Three diagnostic approaches without stopping: (1) Stroboscope \u2014 freeze rotor, visual diode inspection. (2) Voltmeter \u2014 check for unbalanced phase voltages or reduced output. (3) If accessible, measure AC ripple on AVR output (field supply side). Full confirmation requires stopping, dismantling the rotating assembly, and testing each diode with a multimeter.", "id": "T01_NEW_020", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "Describe the control loop of an AVR in one sentence.", "a": "AVR senses output voltage, compares to setpoint, and adjusts field current via thyristors to maintain constant voltage", "opts": ["AVR measures current and adjusts frequency", "AVR senses output voltage, compares to setpoint, and adjusts field current via thyristors to maintain constant voltage", "AVR controls governor speed to regulate voltage", "AVR switches loads on/off to maintain stable voltage"], "exp": "It's a closed-loop feedback control: Sense (voltage transformer samples output) \u2192 Compare (error amplifier: actual vs. setpoint) \u2192 Actuate (thyristor/transistor varies excitation current) \u2192 Effect (field current changes \u2192 flux changes \u2192 EMF changes). Response time: typically 20-200ms.", "id": "T01_NEW_021", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "The SOLAS steady-state voltage regulation requirement is \u00b12.5%. What does this mean practically?", "a": "From zero load to full rated load, the terminal voltage must not deviate more than \u00b12.5% from the rated value", "opts": ["Voltage can vary by 2.5% per second during operation", "From zero load to full rated load, the terminal voltage must not deviate more than \u00b12.5% from the rated value", "2.5% variation is acceptable during paralleling only", "The AVR must respond within 2.5 seconds"], "exp": "For a 440V system: \u00b12.5% means voltage must stay within 429V\u2013451V under any load from 0 to 100%. This is tested during sea trials: connect full rated load, then disconnect \u2014 voltage must not go outside 429-451V at steady state. The transient (instant response) allowance is \u00b110%.", "id": "T01_NEW_022", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "What does the 'stability' trimmer on an AVR control?", "a": "Controls the damping of the AVR response \u2014 prevents hunting/oscillation of terminal voltage", "opts": ["Sets the output voltage setpoint", "Controls reactive load sharing", "Controls the damping of the AVR response \u2014 prevents hunting/oscillation of terminal voltage", "Adjusts the frequency trim via governor link"], "exp": "If stability trimmer is set too low \u2192 AVR is sluggish, slow response to load changes \u2192 voltage dips. Too high \u2192 AVR over-corrects \u2192 voltage oscillates (hunts). Correct setting: smooth response that reaches steady state without overshoot. Adjusted during commissioning while monitoring a scope or voltmeter.", "id": "T01_NEW_023", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "What happens to terminal voltage when two generators run in parallel and one AVR is set significantly higher than the other?", "a": "Higher-set AVR supplies all the reactive current (kVAR) \u2014 the other machine operates near unity PF or goes capacitive", "opts": ["Both machines maintain equal voltage and share kVAR equally", "Higher-set AVR supplies all the reactive current (kVAR) \u2014 the other machine operates near unity PF or goes capacitive", "Frequency difference causes one machine to trip on reverse power", "Both machines trip on overcurrent simultaneously"], "exp": "In parallel, both machines must have the same terminal voltage (they're connected to the same busbar). The machine with higher AVR setpoint 'pushes' more reactive current into the bus. The other machine absorbs it \u2014 effectively operating at leading PF. This causes circulating reactive current and overheating of the over-excited machine. AVR droop prevents this.", "id": "T01_NEW_024", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "Define 'AVR droop' and explain its purpose in parallel operation.", "a": "Droop = intentional voltage reduction as kVAR load increases; ensures stable reactive load sharing between parallel machines", "opts": ["Droop = voltage reduction on no-load for safety", "Droop = intentional voltage reduction as kVAR load increases; ensures stable reactive load sharing between parallel machines", "Droop = speed reduction when overloaded", "Droop = frequency compensation during load shedding"], "exp": "Without droop: two AVRs both trying to hold exact voltage \u2192 one machine 'wins' and takes all reactive current \u2192 unstable. With droop: as machine A takes more kVAR, its terminal voltage droops slightly \u2192 AVR backs off \u2192 load redistributes. Droop = (no-load V - full-load V) / rated V \u00d7 100%. Typical: 2-5%.", "id": "T01_NEW_025", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "Before performing an IR (megger) test, the ETO forgets to disconnect the AVR. What are the TWO consequences?", "a": "(1) Megger voltage damages AVR semiconductors; (2) AVR back-feeds current into winding giving false (high) IR reading", "opts": ["No consequences \u2014 modern AVRs are rated for megger voltage", "(1) Megger voltage damages AVR semiconductors; (2) AVR back-feeds current into winding giving false (high) IR reading", "(1) AVR blows its fuse; (2) Megger shows zero reading", "(1) Field winding burns out; (2) Stator winding gets double voltage"], "exp": "Consequence 1: 500-1000V DC from megger is far above AVR component ratings (thyristors, capacitors, transistors typically rated 400-600V with margins). Irreversible damage likely. Consequence 2: AVR senses an 'undervoltage' (machine not running) and tries to boost excitation \u2014 feeds current back through field winding into megger circuit \u2192 falsely elevated IR reading.", "id": "T01_NEW_026", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "What component in the AVR directly controls the field current magnitude?", "a": "Thyristors (SCRs) or power transistors \u2014 phase-angle fired or PWM controlled to vary DC output to exciter field", "opts": ["A variable transformer (variac)", "A mechanical rheostat", "Thyristors (SCRs) or power transistors \u2014 phase-angle fired or PWM controlled to vary DC output to exciter field", "A relay that switches fixed resistors"], "exp": "Modern AVRs use thyristors (SCRs) in a phase-controlled rectifier \u2014 by varying the firing angle, the average DC output to the exciter field is varied. Some use IGBT transistors with PWM control. Older AVRs used carbon pile regulators (mechanical). The firing angle/duty cycle is controlled by the error amplifier signal.", "id": "T01_NEW_027", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "The terminal voltage is set at 445V but the surveyor says it should be 440V. Which trimmer do you adjust and which way?", "a": "Reduce the 'Voltage Adjust' trimmer \u2014 this lowers the AVR's reference setpoint, reducing field current and output voltage", "opts": ["Increase the Droop trimmer", "Reduce the 'Voltage Adjust' trimmer \u2014 this lowers the AVR's reference setpoint, reducing field current and output voltage", "Adjust the governor speed trimmer downward", "Increase the Stability trimmer"], "exp": "Voltage Adjust trimmer sets the target voltage. Current output 445V > desired 440V \u2192 reduce voltage setpoint. Turn the trimmer down (usually counterclockwise) in small increments, monitor voltmeter. Adjust under representative load (typically 50-75% rated load) for best accuracy. Log the before/after reading.", "id": "T01_NEW_028", "topic": "T01_Alternator"}, {"cat": "RM", "q": "Why might an alternator lose its residual magnetism?", "a": "Large external discharge (short circuit, capacitor discharge), prolonged storage, degaussing nearby, or reverse-polarity field connection", "opts": ["Excessive lubrication of bearings", "Large external discharge (short circuit, capacitor discharge), prolonged storage, degaussing nearby, or reverse-polarity field connection", "Running at low speed for long periods", "AVR malfunction during load shedding"], "exp": "Residual magnetism can be erased by: (1) External magnetic field opposing the existing one \u2014 nearby degaussing operations. (2) Capacitor discharge or short circuit creating a demagnetising pulse. (3) Very long storage without running. (4) Incorrectly polarity-flashing. Any of these can leave the rotor with insufficient residual flux to bootstrap voltage buildup.", "id": "T01_NEW_029", "topic": "T01_Alternator"}, {"cat": "RM", "q": "An alternator at rated speed shows 5V on voltmeter instead of 440V. What is the most likely cause?", "a": "Very low residual magnetism \u2014 insufficient to bootstrap voltage buildup; flashing required", "opts": ["Governor has failed \u2014 speed is too low", "Very low residual magnetism \u2014 insufficient to bootstrap voltage buildup; flashing required", "Main busbar has shorted", "All three phases are open circuit"], "exp": "5V at rated speed suggests some magnetism exists but insufficient for full voltage buildup. This points to degraded (not completely lost) residual magnetism. Check: Is voltmeter accurate? Is speed actually at rated? If both confirmed \u2192 attempt flashing with 12-24V battery to boost residual magnetism \u2192 voltage should build to rated.", "id": "T01_NEW_030", "topic": "T01_Alternator"}, {"cat": "RM", "q": "During flashing: the battery is connected but voltage does NOT build up after disconnection. Next step?", "a": "Check polarity was correct; if polarity was wrong, re-flash with OPPOSITE polarity; if polarity correct, investigate AVR and field circuit", "opts": ["Apply higher voltage battery (48V)", "Check polarity was correct; if polarity was wrong, re-flash with OPPOSITE polarity; if polarity correct, investigate AVR and field circuit", "Repeat flashing 10 times \u2014 residual builds gradually", "Call superintendent \u2014 machine is beyond repair"], "exp": "If polarity was wrong: the flash destroyed existing residual magnetism instead of restoring it. Re-flash with correct polarity. If polarity was correct but no buildup: (1) Is machine at rated speed? (2) Is AVR functioning? (3) Check field winding continuity (resistance test). (4) Check rotating diodes (brushless). Don't keep flashing blindly.", "id": "T01_NEW_031", "topic": "T01_Alternator"}, {"cat": "RM", "q": "What is the correct battery voltage for flashing an alternator?", "a": "12V or 24V DC battery \u2014 brief connection of 2-3 seconds only", "opts": ["6V DC \u2014 lower risk of damage", "240V DC from shore supply", "12V or 24V DC battery \u2014 brief connection of 2-3 seconds only", "110V DC from emergency battery bank"], "exp": "12V or 24V (typical ship's battery) is sufficient to restore residual magnetism. Higher voltage risks overheating the field winding. Duration must be short (2-3 seconds) \u2014 sustained current could damage the winding. The goal is just to magnetise the rotor core, not to supply steady field current.", "id": "T01_NEW_032", "topic": "T01_Alternator"}, {"cat": "RM", "q": "After successfully flashing, what should you observe at the voltmeter?", "a": "Voltage builds progressively from low value to near-rated value as the bootstrap cycle takes effect", "opts": ["Voltage jumps instantly to exactly rated value", "Voltage builds progressively from low value to near-rated value as the bootstrap cycle takes effect", "Voltage remains at battery voltage level", "Voltage surges to 120% then settles"], "exp": "The bootstrap cycle: residual \u2192 small voltage \u2192 field current \u2192 more flux \u2192 more voltage \u2192 field current \u2192 ... This is progressive, not instant. You should see the voltmeter needle rise steadily over a few seconds until the AVR takes control and stabilises at rated voltage. If voltage doesn't build \u2192 residual still insufficient \u2192 investigate further.", "id": "T01_NEW_033", "topic": "T01_Alternator"}, {"cat": "SY", "q": "State the FOUR conditions that must be met before closing the ACB to parallel two generators.", "a": "(1) Same voltage, (2) Same frequency, (3) Same phase sequence, (4) Phase angle difference = 0\u00b0 (in phase)", "opts": ["(1) Same kVA rating, (2) Same voltage, (3) Same brand, (4) Same fuel type", "(1) Same voltage, (2) Same frequency, (3) Same phase sequence, (4) Phase angle difference = 0\u00b0 (in phase)", "(1) Same voltage, (2) Same frequency, (3) Different phase to cancel", "(1) Same current, (2) Same voltage, (3) Same fuel consumption"], "exp": "All four must be satisfied simultaneously: (1) Voltage: equal magnitudes, typically within \u00b12%. (2) Frequency: equal Hz \u2014 synchroscope pointer stopped. (3) Phase sequence: R-Y-B must match (checked once at commissioning). (4) Phase angle: 0\u00b0 \u2014 synchroscope pointer at 12 o'clock. Miss any one \u2192 current surge on ACB closing.", "id": "T01_NEW_034", "topic": "T01_Alternator"}, {"cat": "SY", "q": "The synchroscope pointer rotates ANTICLOCKWISE (CCW). What does this mean and what action do you take?", "a": "Incoming generator is SLOWER than busbar \u2014 increase governor setting to speed it up", "opts": ["Incoming generator is faster \u2014 reduce governor speed", "Incoming generator is SLOWER than busbar \u2014 increase governor setting to speed it up", "Phase sequence is wrong \u2014 swap two phases", "Voltage is too low \u2014 increase AVR setting"], "exp": "CCW rotation = incoming lags busbar = incoming machine is slow. Action: increase governor (fuel) on incoming machine to raise speed \u2192 pointer slows then stops \u2192 accelerate to just barely CW \u2192 close ACB when pointer at 12 o'clock moving slowly CW. Never close while pointer is moving CCW \u2014 machine will motor.", "id": "T01_NEW_035", "topic": "T01_Alternator"}, {"cat": "SY", "q": "Why is the ACB closed when the synchroscope pointer is 'just past 11 o'clock moving slowly CW' rather than exactly at 12?", "a": "ACB closing takes ~80-100ms \u2014 closing just before 12 o'clock accounts for this delay so actual closing occurs at or near 12", "opts": ["It doesn't matter \u2014 close at any position", "ACB closing takes ~80-100ms \u2014 closing just before 12 o'clock accounts for this delay so actual closing occurs at or near 12", "The 11 o'clock position is in-phase for 50 Hz systems", "The synchroscope is 30 seconds behind actual phase"], "exp": "Mechanical ACBs have a closing time of 80-150ms. If you wait until exactly 12 o'clock and then press close, the breaker physically closes 80-150ms later \u2014 by which time the phase angle has advanced slightly. Anticipating this by closing at ~11 o'clock (for slow-moving pointer) means the breaker contacts meet very close to true in-phase.", "id": "T01_NEW_036", "topic": "T01_Alternator"}, {"cat": "SY", "q": "What is the 'dark lamp' method of synchronisation?", "a": "Three lamps connected between corresponding phases of incoming and busbar \u2014 lamps are dark when in phase, close ACB when ALL three are simultaneously dark", "opts": ["Connect one lamp across the ACB \u2014 close when it dims", "Three lamps connected between corresponding phases of incoming and busbar \u2014 lamps are dark when in phase, close ACB when ALL three are simultaneously dark", "Use flashlight to illuminate the pointer \u2014 close at 12 o'clock", "Three lamps connected in star \u2014 close when all equally bright"], "exp": "Each lamp sees the voltage difference between corresponding phases. When in phase: V_diff = 0 \u2192 lamps dark. When out of phase: V_diff = 2V \u2192 lamps bright. They cycle bright-dim-dark at the difference frequency. Close when ALL THREE dark simultaneously \u2014 this confirms phase angle AND frequency match. One dark lamp alone is not sufficient.", "id": "T01_NEW_037", "topic": "T01_Alternator"}, {"cat": "SY", "q": "What happens to the 'bright lamp' synchronisation method \u2014 when should the ACB be closed?", "a": "Close when all three lamps are EQUALLY BRIGHT", "opts": ["Close when all three lamps are dark", "Close when all three lamps are EQUALLY BRIGHT", "Close when two are bright and one is dark", "Close when lamps stop flickering"], "exp": "Bright lamp: lamps connected in cross-phase sequence (not corresponding phases). At synchronism, each lamp sees 1/3 of line voltage difference \u2014 all equal brightness. Out of sync: one bright, one dim, one dark \u2014 rotating pattern. Close at equal brightness. Dark lamp is more common \u2014 brighter/clearer signal to operator.", "id": "T01_NEW_038", "topic": "T01_Alternator"}, {"cat": "SY", "q": "The synchroscope is showing 12 o'clock but rotating VERY FAST CW. What should you do?", "a": "DO NOT close ACB \u2014 reduce governor speed until pointer barely moves CW before closing", "opts": ["Close ACB immediately \u2014 it's at 12 o'clock position", "DO NOT close ACB \u2014 reduce governor speed until pointer barely moves CW before closing", "Increase AVR voltage to match busbar", "Close ACB and let reverse power relay trip it if wrong"], "exp": "Fast rotation means large speed/frequency difference \u2014 even at 12 o'clock, the phase angle is changing rapidly. By the time ACB closes (80-100ms), phase angle has already shifted significantly. Result: large current surge, possible overcurrent trip. Speed should be adjusted so pointer rotates at <1 RPM \u2014 approaching 12 very slowly \u2014 before closing.", "id": "T01_NEW_039", "topic": "T01_Alternator"}, {"cat": "SY", "q": "How do you determine the correct PHASE SEQUENCE of a new alternator before paralleling?", "a": "Use a phase sequence meter (Ferraris disc type or electronic) \u2014 verify R-Y-B rotation matches existing busbar", "opts": ["Check the nameplate \u2014 phase sequence is always R-Y-B", "Use a phase sequence meter (Ferraris disc type or electronic) \u2014 verify R-Y-B rotation matches existing busbar", "Measure voltage between phases \u2014 if equal, sequence is correct", "Connect the synchroscope \u2014 it will indicate wrong sequence"], "exp": "Phase sequence must be physically checked for any new or rewound machine. A Ferraris disc (small induction motor with disc) rotates CW for R-Y-B and CCW for R-B-Y. Electronic meters have LED indicators. Synchroscope will NOT indicate wrong phase sequence \u2014 it just shows phase angle. Wrong sequence gives large currents on ACB closing even if synchroscope shows 12 o'clock.", "id": "T01_NEW_040", "topic": "T01_Alternator"}, {"cat": "LS", "q": "Generator G1 shows high kW output, G2 shows low kW. Both governors are set equally. What is the cause?", "a": "Governor droop settings differ between the two machines \u2014 one governor is more responsive than the other", "opts": ["AVR settings are different", "Generator rotor bearing friction is different", "Governor droop settings differ between the two machines \u2014 one governor is more responsive than the other", "Prime mover fuel viscosity is different"], "exp": "Equal governor settings should give equal kW in theory. But if droop settings differ (one at 3%, one at 5%), the lower-droop machine tends to take more load. Check and equalise droop first. If still unequal: adjust speed trimmer on the overloaded machine to reduce its speed slightly \u2192 load shifts to G2.", "id": "T01_NEW_041", "topic": "T01_Alternator"}, {"cat": "LS", "q": "Generators G1 and G2 have equal kW output but G1 has much higher current than G2. What needs adjustment?", "a": "AVR droop on G1 needs to be increased \u2014 G1 is supplying too much reactive (kVAR) current", "opts": ["Governor droop on G1 needs adjustment", "AVR droop on G1 needs to be increased \u2014 G1 is supplying too much reactive (kVAR) current", "G1 has incorrect phase sequence", "G2 has a short circuit in field winding"], "exp": "Equal kW (real power) but unequal current means unequal kVAR (reactive power) sharing. Higher current on G1 = G1 more heavily excited = G1 supplying more reactive current. Fix: increase AVR droop on G1 (or decrease droop on G2) until currents equalise. Check: after adjustment, kW should remain equal.", "id": "T01_NEW_042", "topic": "T01_Alternator"}, {"cat": "LS", "q": "Explain why adding load to one parallel generator automatically causes the other to share the load.", "a": "Governor droop: as load increases, engine speed droops \u2192 governor detects droop and increases fuel \u2192 both governors respond to the common frequency change", "opts": ["The ACB automatically reduces current to the loaded machine", "Governor droop: as load increases, engine speed droops \u2192 governor detects droop and increases fuel \u2192 both governors respond to the common frequency change", "AVR automatically reduces excitation on loaded machine", "Load is balanced by the busbar protection relay"], "exp": "Both generators share the same busbar frequency. Droop governors: if frequency drops (more load on busbar), both governors increase fuel \u2192 both machines produce more power \u2192 load is shared. The droop characteristic ensures stable sharing: if one machine tries to take too much load, its speed droops more, causing governor to back off slightly.", "id": "T01_NEW_043", "topic": "T01_Alternator"}, {"cat": "LS", "q": "What is 'load transfer' and how is it done when taking a generator off-line?", "a": "Gradually reduce outgoing machine's governor (kW \u2192 0) then reduce AVR (kVAR \u2192 0 or small negative) before opening ACB", "opts": ["Directly open ACB \u2014 remaining generator takes load automatically", "Gradually reduce outgoing machine's governor (kW \u2192 0) then reduce AVR (kVAR \u2192 0 or small negative) before opening ACB", "Increase load on remaining generator first, then trip outgoing", "Use preferential trip to shed the outgoing generator's load"], "exp": "Sequence: (1) Increase governor on remaining machine to take load. (2) Reduce governor on outgoing machine until kW \u2192 near zero. (3) Reduce AVR on outgoing machine until its current \u2192 near zero (watch ammeter). (4) Verify outgoing machine shows near-zero current. (5) Open ACB. Never open ACB while outgoing machine is still carrying significant load \u2014 causes voltage surge.", "id": "T01_NEW_044", "topic": "T01_Alternator"}, {"cat": "LS", "q": "What is 'hunting' in a parallel generator system?", "a": "Oscillation of load between generators \u2014 caused by incorrect governor droop settings or governor instability", "opts": ["Physical vibration of generator from unbalanced rotor", "Oscillation of load between generators \u2014 caused by incorrect governor droop settings or governor instability", "Hunting is normal during frequency transients", "High-frequency noise from AVR thyristors"], "exp": "Hunting: kW on G1 increases \u2192 G1 takes more busbar load \u2192 G2 reduces \u2192 G2 governor over-responds \u2192 G2 overshoots \u2192 G1 reduces \u2192 cycle repeats. Symptoms: wildly fluctuating ammeters and kW meters. Cause: governor isochronous mode (no droop) or improper droop settings. Fix: enable droop or re-tune governor stability.", "id": "T01_NEW_045", "topic": "T01_Alternator"}, {"cat": "PR", "q": "List EIGHT protections fitted to a marine alternator.", "a": "OCR, Over-voltage, Under-voltage, Differential, Reverse power, Earth fault, Bearing temp (PT100), Winding temp (thermistor), Preferential trip", "opts": ["Only OCR and earth fault are mandatory", "OCR, Over-voltage, Under-voltage, Differential, Reverse power, Earth fault, Bearing temp (PT100), Winding temp (thermistor), Preferential trip", "Only voltage protection is fitted \u2014 current is monitored by AVR", "OCR, reverse power, and overspeed are the three mandatory ones"], "exp": "Full list: (1) OCR \u2014 overcurrent. (2) Over-voltage ~110%. (3) Under-voltage ~85%. (4) Differential relay \u2014 internal faults. (5) Reverse power relay ~5-10% rated kW reverse. (6) Earth fault \u2014 stator earth (95% coverage). (7) Bearing temperature PT100 \u2014 alarm 80\u00b0C, trip 95\u00b0C. (8) Winding thermistor \u2014 Class F limit 155\u00b0C. (9) Preferential trip \u2014 sustained overload load shedding.", "id": "T01_NEW_046", "topic": "T01_Alternator"}, {"cat": "PR", "q": "Why is the differential protection relay considered the 'fastest and most sensitive' protection for internal alternator faults?", "a": "It operates instantaneously on any current difference between ends of the winding \u2014 does not need to wait for sustained overcurrent", "opts": ["It has a mechanical response spring that is the fastest actuator", "It operates instantaneously on any current difference between ends of the winding \u2014 does not need to wait for sustained overcurrent", "It is connected directly to the main busbar for fastest detection", "It monitors all three phases simultaneously while OCR monitors only one"], "exp": "Differential relay: CT at each end of stator winding compares ingoing and outgoing current. Under normal operation: exactly equal (Kirchhoff's law). Internal fault: current divides \u2014 some goes to earth via fault \u2192 unequal CTs \u2192 relay operates INSTANTLY with no intentional time delay. Highly sensitive to low-level internal faults that OCR would not detect.", "id": "T01_NEW_047", "topic": "T01_Alternator"}, {"cat": "PR", "q": "The preferential trip relay has a dashpot. A large motor starts and overloads the generator for 8 seconds. The dashpot is set to 10 seconds. What happens?", "a": "No load shedding \u2014 motor starting overload clears within 10-second dashpot delay and preferential trip does not operate", "opts": ["Preferential trip operates after 8 seconds and sheds loads", "No load shedding \u2014 motor starting overload clears within 10-second dashpot delay and preferential trip does not operate", "Generator trips immediately on overcurrent", "AVR reduces voltage to protect the generator"], "exp": "This is exactly the purpose of the dashpot: transient overloads (motor starting, thruster acceleration) last only seconds \u2014 dashpot prevents unnecessary load shedding. Only if overload persists beyond the set time (10 sec in this example) does the trip operate. This avoids nuisance trips during normal operations.", "id": "T01_NEW_048", "topic": "T01_Alternator"}, {"cat": "PR", "q": "Under-voltage relay is set at 85% rated voltage. A 440V system drops to 380V due to a fault. Does the UV relay operate?", "a": "Yes \u2014 380V is 86.4% of 440V which is close to 85% threshold; sustained drop to this level will operate the relay", "opts": ["No \u2014 380V is too close to threshold for relay to operate", "Yes \u2014 380V is 86.4% of 440V which is close to 85% threshold; sustained drop to this level will operate the relay", "UV relay only operates below 50% rated voltage", "UV relay is disabled during fault conditions"], "exp": "85% of 440V = 374V. At 380V (86.4%), the relay is just above threshold \u2014 may not operate immediately. But if voltage continues to drop to 374V, UV relay operates. UV relay typically has a short time delay (0.5-2 sec) to avoid nuisance trips on transient dips. Sustained undervoltage causes motor stalling \u2014 UV relay disconnects generator/loads.", "id": "T01_NEW_049", "topic": "T01_Alternator"}, {"cat": "PR", "q": "What is the PT100 and how does it work in bearing temperature monitoring?", "a": "PT100 = Platinum Resistance Thermometer with 100\u03a9 at 0\u00b0C \u2014 resistance increases linearly with temperature; connected to monitoring panel", "opts": ["PT100 = Pressure Temperature sensor rated for 100 bar", "PT100 = Platinum Resistance Thermometer with 100\u03a9 at 0\u00b0C \u2014 resistance increases linearly with temperature; connected to monitoring panel", "PT100 is a thermocouple that generates voltage proportional to temperature", "PT100 is an optical sensor that detects bearing colour change"], "exp": "PT100 works on resistance-temperature relationship: R = 100 \u00d7 (1 + 0.00385 \u00d7 T\u00b0C). At 80\u00b0C: R \u2248 130.8\u03a9 \u2192 alarm. At 95\u00b0C: R \u2248 136.6\u03a9 \u2192 trip. Monitoring panel converts resistance to temperature reading. PT100s are embedded in bearing housings. Very stable and accurate \u2014 suitable for continuous monitoring.", "id": "T01_NEW_050", "topic": "T01_Alternator"}, {"cat": "PR", "q": "Why does earth fault protection typically only protect 95% of the stator winding?", "a": "The 5% of winding nearest the star-point (neutral) has insufficient voltage to earth to drive the earth fault relay", "opts": ["The remaining 5% is protected by the overcurrent relay", "The 5% of winding nearest the star-point (neutral) has insufficient voltage to earth to drive the earth fault relay", "The neutral end is earthed anyway so earth faults there are harmless", "The CTs cannot be installed at the star-point end due to space"], "exp": "Earth fault relay operates from the voltage developed between the fault point and earth. At the neutral (star) point: voltage to earth \u2248 0V \u2192 a fault there develops no driving voltage for the relay. As the fault point moves toward the line terminal, voltage increases. The relay has a minimum voltage threshold \u2192 typically 5% of winding (neutral end) below this threshold is unprotected.", "id": "T01_NEW_051", "topic": "T01_Alternator"}, {"cat": "MT", "q": "What is the Polarisation Index (PI) test and why is it more reliable than a single IR reading?", "a": "PI = IR at 10 min / IR at 1 min \u2014 ratio shows whether resistance is rising (good dry insulation) or flat/falling (wet/contaminated)", "opts": ["PI measures the peak insulation resistance during 10 minutes", "PI = IR at 10 min / IR at 1 min \u2014 ratio shows whether resistance is rising (good dry insulation) or flat/falling (wet/contaminated)", "PI is the number of megohms per kilovolt of test voltage", "PI measures leakage current at rated operating voltage"], "exp": "Good dry insulation: resistance keeps rising over time as polarisation occurs \u2192 PI > 2. Wet or contaminated insulation: resistance stays constant or drops \u2192 PI < 1. A machine might show 5 M\u03a9 at 1 min and 15 M\u03a9 at 10 min \u2192 PI = 3 \u2192 GOOD. Another shows 5 M\u03a9 at 1 min and 4 M\u03a9 at 10 min \u2192 PI = 0.8 \u2192 DANGEROUS. Single reading doesn't reveal this trend.", "id": "T01_NEW_052", "topic": "T01_Alternator"}, {"cat": "MT", "q": "IR test shows 0.8 M\u03a9 on a 440V alternator stator winding. What action do you take?", "a": "Do NOT energise \u2014 0.8 M\u03a9 is below 1 M\u03a9 minimum; investigate cause (moisture, contamination), dry out winding, retest", "opts": ["0.8 M\u03a9 is acceptable for wet conditions \u2014 run at 50% load", "Do NOT energise \u2014 0.8 M\u03a9 is below 1 M\u03a9 minimum; investigate cause (moisture, contamination), dry out winding, retest", "Megger again with 1000V to get a more accurate reading", "Apply varnish to winding and retest immediately"], "exp": "1 M\u03a9 is the absolute minimum. 0.8 M\u03a9 = DO NOT RUN. Actions: (1) Check for obvious moisture (condensation, bilge water ingress). (2) Use anti-condensation heaters at low temperature to dry gradually \u2014 do not apply heat suddenly to wet windings (thermal shock). (3) Blow through with dry compressed air (low pressure). (4) Retest after 4-6 hours heating. Log all readings.", "id": "T01_NEW_053", "topic": "T01_Alternator"}, {"cat": "MT", "q": "How do you safely discharge a stator winding after megger testing?", "a": "Connect a high-resistance discharge resistor from each terminal to earth first, then short to earth \u2014 never short directly", "opts": ["Remove megger leads \u2014 charge dissipates naturally in 10 seconds", "Connect a high-resistance discharge resistor from each terminal to earth first, then short to earth \u2014 never short directly", "Short all terminals together \u2014 no earth needed", "Leave for 1 hour \u2014 capacitive charge self-discharges"], "exp": "Megger charges winding capacitance to test voltage (500-1000V). Direct short to earth \u2192 arc \u2192 shock risk. Procedure: (1) After stopping megger, apply high-resistance (10k\u03a9-100k\u03a9) discharge resistor between winding terminal and earth. (2) Allow 4\u00d7 the test time for discharge. (3) Then apply earth bonding lead. Time constant = R\u00d7C \u2014 with large winding capacitance, can take minutes.", "id": "T01_NEW_054", "topic": "T01_Alternator"}, {"cat": "MT", "q": "What routine checks should you perform on a running alternator during your watch? (Name 6)", "a": "Voltage, current, frequency, power factor, bearing temperature, winding temperature, vibration, abnormal noise, AVR stability", "opts": ["Only check voltage \u2014 other parameters are monitored automatically", "Voltage, current, frequency, power factor, bearing temperature, winding temperature, vibration, abnormal noise, AVR stability", "Perform IR test every watch", "Remove slip ring cover and inspect during running"], "exp": "Running checks (no shutdown): (1) Switchboard meters \u2014 V, A, Hz, kW, PF. (2) Trending \u2014 compare to previous watch readings. (3) Bearing temperature \u2014 PT100 readings or touch-check housing. (4) Listen \u2014 abnormal noise (grinding = bearing, whining = rotor rub). (5) Feel vibration \u2014 excessive = imbalance or bearing. (6) Check AVR stability \u2014 is voltage steady? Log everything.", "id": "T01_NEW_055", "topic": "T01_Alternator"}, {"cat": "MT", "q": "An alternator has been sitting in drydock for 3 months in a cold humid climate. Before restarting, what is the FIRST electrical check?", "a": "Megger test (IR test) all three phases to earth and between phases before energising", "opts": ["Check bearing oil level", "Megger test (IR test) all three phases to earth and between phases before energising", "Check fuel system and prime mover", "Connect to shore power and test with full load"], "exp": "Cold humid drydock = high condensation risk. Windings absorb moisture \u2192 IR drops dramatically. NEVER energise a machine without first confirming IR is acceptable (>1M\u03a9, PI >2 ideally). If IR is low: dry out with anti-condensation heaters before energising. Also check: oil, fuel, cooling water, governor operation, and perform no-load run before taking any load.", "id": "T01_NEW_056", "topic": "T01_Alternator"}, {"cat": "MT", "q": "What is the purpose of blowing out a running alternator with dry compressed air?", "a": "Remove carbon brush dust, accumulated dirt, and moisture from air passages and winding surfaces to prevent tracking and overheating", "opts": ["Cool the bearings during heavy load operation", "Remove carbon brush dust, accumulated dirt, and moisture from air passages and winding surfaces to prevent tracking and overheating", "Test the ventilation fan efficiency", "The compressed air re-magnetises the rotor during service"], "exp": "Carbon brush dust (from slip rings) and general dust accumulate in ventilation passages and on winding surfaces. Conductive dust on windings reduces surface insulation resistance \u2192 tracking (surface arcing). Blocked ventilation \u2192 overheating. Low-pressure dry compressed air (max 2 bar) blown through clears passages. Collect dust \u2014 don't just blow it into bearing housings.", "id": "T01_NEW_057", "topic": "T01_Alternator"}, {"cat": "AG", "q": "What is the typical specification for air gap variation in a marine alternator?", "a": "Air gap should be uniform within \u00b110% of the mean value around the circumference", "opts": ["Air gap must be exactly equal all around \u2014 0% variation allowed", "Air gap should be uniform within \u00b110% of the mean value around the circumference", "Up to \u00b125% variation is acceptable", "Air gap variation is not critical \u2014 only total clearance matters"], "exp": "Manufacturers specify air gap tolerance typically as \u00b110% of mean. Example: if mean air gap = 3mm, acceptable range = 2.7-3.3mm. Variation beyond \u00b110% indicates bearing wear, rotor eccentricity, or stator bore distortion. The variation creates unbalanced magnetic pull (UMP) proportional to eccentricity \u2014 self-aggravating force.", "id": "T01_NEW_058", "topic": "T01_Alternator"}, {"cat": "AG", "q": "How many measurement points per pole are typically used when measuring alternator air gap?", "a": "4 measurement points per pole (top, bottom, left, right) \u2014 or at 90\u00b0 intervals around the full circumference", "opts": ["1 point per pole is sufficient", "4 measurement points per pole (top, bottom, left, right) \u2014 or at 90\u00b0 intervals around the full circumference", "16 measurements total regardless of pole count", "Only one measurement needed at the largest gap position"], "exp": "4 points per pole gives a complete picture of gap uniformity. For a 4-pole machine: 4 \u00d7 4 = 16 measurements. The measurements are taken by inserting feeler gauges through ventilation slots or access openings. Results tabulated: any position deviating by >10% from mean requires investigation.", "id": "T01_NEW_059", "topic": "T01_Alternator"}, {"cat": "AG", "q": "During maintenance, air gap is measured and found to be 2mm on one side and 4mm on the opposite side. What does this indicate?", "a": "Rotor is eccentric \u2014 likely a worn bearing causing the rotor to sag toward the smaller gap side", "opts": ["Stator winding insulation has expanded", "Rotor is eccentric \u2014 likely a worn bearing causing the rotor to sag toward the smaller gap side", "Air gap variation is normal and requires no action", "Rotor has been machined incorrectly \u2014 scrap and replace"], "exp": "2mm vs 4mm = 100% variation (vs acceptable \u00b110%). The rotor centre is not coincident with the stator bore centre \u2014 it has shifted toward the 2mm side. Most likely cause: worn bearing allowing rotor to sag. Also possible: bent shaft, bearing pedestal misalignment, or improper rotor installation after rewind. Check and replace bearing, realign, recheck gap.", "id": "T01_NEW_060", "topic": "T01_Alternator"}, {"cat": "OS", "q": "What is the difference between the governor trip and the mechanical overspeed trip?", "a": "Governor trip = normal speed control; Mechanical overspeed trip = emergency backup that activates at 110-115% speed to prevent destruction", "opts": ["They are the same device with different names", "Governor trip = normal speed control; Mechanical overspeed trip = emergency backup that activates at 110-115% speed to prevent destruction", "Mechanical trip = faster response; governor = backup", "Governor only controls fuel \u2014 no trip function"], "exp": "Governor maintains normal operating speed. If governor fails \u2192 speed rises uncontrolled \u2192 mechanical overspeed trip activates at 110-115% rated speed as a last resort. Mechanical trip typically actuates a fuel cutoff lever or solenoid directly \u2014 independent of electronic governor. It's a fail-safe backup.", "id": "T01_NEW_061", "topic": "T01_Alternator"}, {"cat": "OS", "q": "A diesel alternator rated at 1500 RPM has its overspeed trip set at 113%. At what RPM does it trip?", "a": "1695 RPM", "opts": ["1650 RPM", "1695 RPM", "1725 RPM", "1500 RPM"], "exp": "Trip RPM = rated RPM \u00d7 trip % = 1500 \u00d7 1.13 = 1695 RPM. This is within the typical 110-115% range. After the test, verify the trip reset and check that the mechanical linkage is undamaged. Log the actual trip speed and compare to the design specification.", "id": "T01_NEW_062", "topic": "T01_Alternator"}, {"cat": "OS", "q": "During overspeed trip test, the ACB must be OPEN before starting. Why?", "a": "To prevent frequency surge from feeding into the main busbar and damaging other equipment and motors", "opts": ["To allow the machine to accelerate freely without generator load", "To prevent frequency surge from feeding into the main busbar and damaging other equipment and motors", "ACB open allows higher test speed to be reached", "Required to reset the mechanical trip mechanism first"], "exp": "Two reasons: (1) If generator is connected to busbar at 113% speed, it generates 56.5 Hz (for 50 Hz) \u2014 all connected motors over-speed simultaneously \u2192 can damage equipment. (2) With ACB open, the machine can freely accelerate to trip speed without electrical load affecting the test. Always open ACB before testing overspeed.", "id": "T01_NEW_063", "topic": "T01_Alternator"}, {"cat": "BT", "q": "What loads must the emergency generator supply within 45 seconds of blackout per SOLAS?", "a": "Emergency lighting, navigation lights, steering gear (for 30 min), fire pump, VHF/GMDSS, internal communications, alarms", "opts": ["Only emergency lighting \u2014 other loads connect via UPS", "Emergency lighting, navigation lights, steering gear (for 30 min), fire pump, VHF/GMDSS, internal communications, alarms", "All loads that were connected before blackout", "Only bridge equipment and navigation lights"], "exp": "SOLAS II-1 Reg 42: Emergency services include: (1) Emergency lighting \u2014 all muster stations, escape routes, accommodation. (2) Navigation lights and signals. (3) Steering gear \u2014 must supply for 30 min continuous. (4) Fire detection and alarm. (5) Fire pump. (6) VHF and GMDSS. (7) Internal communications. (8) Emergency bilge pump. (9) Ship's whistle.", "id": "T01_NEW_064", "topic": "T01_Alternator"}, {"cat": "BT", "q": "The ETO times the emergency generator during a blackout test and it takes 52 seconds. Is this acceptable?", "a": "NO \u2014 SOLAS requires 45 seconds maximum; 52 seconds is non-compliant; deficiency must be investigated and corrected before next survey", "opts": ["Yes \u2014 52 seconds is within the 60-second allowance", "NO \u2014 SOLAS requires 45 seconds maximum; 52 seconds is non-compliant; deficiency must be investigated and corrected before next survey", "Only the Class surveyor can decide acceptability", "52 seconds is acceptable for ships over 10 years old"], "exp": "45 seconds is an absolute SOLAS requirement with no tolerance. 52 seconds = non-compliance. Investigate: (1) Battery/pre-heating system \u2014 is DG warm enough? (2) Starter motor condition. (3) Fuel system \u2014 air lock? (4) Governor response speed. (5) Check starting battery state of charge. Correct fault, retest, and ensure acceptable before any port state control inspection.", "id": "T01_NEW_065", "topic": "T01_Alternator"}, {"cat": "BT", "q": "Why must the bridge officer be informed BEFORE a blackout test is conducted?", "a": "Bridge must be in a safe navigational situation \u2014 blackout test must not be conducted during confined waters, high traffic, or bad weather", "opts": ["Bridge officer must operate the emergency generator", "Bridge must be in a safe navigational situation \u2014 blackout test must not be conducted during confined waters, high traffic, or bad weather", "The engine telegraph needs to be set to 'stop'", "Bridge controls the test timing via alarm panel"], "exp": "During the 45 seconds (minimum) between blackout and emergency power: steering is unpowered, radar may lose power, navigation lights are dark. In confined waters, heavy traffic, or poor visibility, this creates serious collision risk. Blackout test should only be conducted in open sea, good visibility, light traffic, with Master's permission.", "id": "T01_NEW_066", "topic": "T01_Alternator"}, {"cat": "SOL", "q": "SOLAS Chapter II-1 Regulation 40 covers what aspect of electrical systems?", "a": "Main source of electrical power \u2014 requirements for generating capacity, voltage regulation, and protection against flooding", "opts": ["Fire detection and fixed suppression systems", "Main source of electrical power \u2014 requirements for generating capacity, voltage regulation, and protection against flooding", "Life-saving appliance electrical requirements", "Emergency battery requirements only"], "exp": "SOLAS II-1 Reg 40: (1) Main electrical power must supply essential services. (2) At least 2 generators must be fitted (for most ships). (3) Loss of any one generator must not leave ship without power for essential services. (4) Voltage regulation within \u00b12.5% steady-state. (5) Protection against flooding of main machinery space.", "id": "T01_NEW_067", "topic": "T01_Alternator"}, {"cat": "SOL", "q": "Where EXACTLY must the emergency generator be located per SOLAS?", "a": "Above the bulkhead deck, in a separate compartment, entirely outside the main machinery space", "opts": ["Below the bulkhead deck, adjacent to ECR", "Above the bulkhead deck, in a separate compartment, entirely outside the main machinery space", "Anywhere above the waterline", "In the forward machinery space only"], "exp": "SOLAS II-1 Reg 42/43: Emergency generator must be: (1) Above the bulkhead (damage control) deck \u2014 so flooding of lower spaces doesn't affect it. (2) OUTSIDE the main machinery space \u2014 fire or flooding in ER cannot disable it. (3) In its own compartment with fire resistance equivalent to 'A-60' class. This ensures it's available in ANY casualty scenario.", "id": "T01_NEW_068", "topic": "T01_Alternator"}, {"cat": "SOL", "q": "How long must the emergency generator be able to supply emergency loads continuously?", "a": "18 hours for passenger ships; 36 hours for cargo ships", "opts": ["6 hours for all ships", "18 hours for passenger ships; 36 hours for cargo ships", "24 hours for all ships", "Until rescued \u2014 no time limit specified"], "exp": "SOLAS II-1 Reg 42/43: Passenger ships: minimum 18 hours. Cargo ships: minimum 36 hours. This reflects different rescue scenarios \u2014 cargo ships may operate far from assistance. The fuel tank for the emergency generator must be sized accordingly, with a dedicated fuel day tank that fills automatically.", "id": "T01_NEW_069", "topic": "T01_Alternator"}, {"cat": "SOL", "q": "What is the SOLAS requirement for the number of main generators on a cargo ship?", "a": "At least 2 generators required; loss of any single generator must not leave essential services without power", "opts": ["Exactly 3 generators \u2014 one active, one standby, one emergency", "At least 2 generators required; loss of any single generator must not leave essential services without power", "Only 1 main generator needed if emergency generator is installed", "4 generators minimum for ships over 10,000 GRT"], "exp": "SOLAS II-1 Reg 40: 'At least 2 generating sets.' The total installed capacity must be sufficient that essential services can be maintained even if the LARGEST single generator fails. In practice, most ships have 2-3 main generators sized so any one can be lost and the others cover essential services.", "id": "T01_NEW_070", "topic": "T01_Alternator"}, {"cat": "FT", "q": "Alternator is running but output voltage is 390V instead of 440V. Governor and speed are correct. What are the possible causes?", "a": "Low excitation: AVR setpoint too low, AVR fault, PMG output low, partial field winding fault, rotating diode failure", "opts": ["Overloaded generator \u2014 reduce load", "Low excitation: AVR setpoint too low, AVR fault, PMG output low, partial field winding fault, rotating diode failure", "Wrong phase rotation", "Stator winding short circuit"], "exp": "Low voltage with correct speed = insufficient excitation. Systematic check: (1) Adjust voltage trimmer \u2014 maybe setpoint is wrong. (2) Check AVR input (PMG) \u2014 is PMG giving correct output? (3) Measure AVR output to exciter field. (4) Check rotating diodes with stroboscope. (5) Measure field winding resistance \u2014 partial short reduces field. (6) Check for excessive load (low PF load can reduce voltage if AVR is at limit).", "id": "T01_NEW_071", "topic": "T01_Alternator"}, {"cat": "FT", "q": "A 440V motor on a ship receives 380V due to voltage dip. What is the effect on motor torque and current?", "a": "Torque \u221d V\u00b2: reduces to (380/440)\u00b2 = 0.745 \u2192 74.5% rated torque; current rises to compensate, risking thermal damage", "opts": ["Torque increases to compensate for lower voltage", "Torque \u221d V\u00b2: reduces to (380/440)\u00b2 = 0.745 \u2192 74.5% rated torque; current rises to compensate, risking thermal damage", "No change \u2014 motor adjusts automatically", "Speed drops 13.6% with no change in current"], "exp": "(380/440)\u00b2 = 0.745 = 74.5% rated torque. If motor is loaded near full torque: torque deficit \u2192 increased slip \u2192 more current \u2192 more heat. The thermal protection (overload relay) is now more critical. For starting: motor start torque (proportional to V\u00b2) also reduced by 25.5% \u2014 large motors may fail to start if connected load has high starting torque requirement.", "id": "T01_NEW_072", "topic": "T01_Alternator"}, {"cat": "FT", "q": "Alternator output current is unbalanced \u2014 R phase 200A, Y phase 200A, B phase 120A. What is the likely cause?", "a": "Unbalanced load between phases, or B phase stator winding partial fault, or B phase CT fault (if readings are from meters)", "opts": ["Governor is hunting \u2014 causing current oscillation", "Unbalanced load between phases, or B phase stator winding partial fault, or B phase CT fault (if readings are from meters)", "Normal variation \u2014 alternators always have some current imbalance", "Reverse power on B phase due to incorrect synchronisation"], "exp": "Unbalanced 3-phase current: (1) Unbalanced load \u2014 most common: single-phase loads, unequally distributed. (2) If all loads seem balanced: check if it's a metering fault (B phase CT open circuit shows zero, not 120A). (3) Winding fault on B phase \u2014 would also cause voltage unbalance. Check: measure line voltages \u2014 if balanced, likely load issue. If voltages also unbalanced \u2192 internal winding problem.", "id": "T01_NEW_073", "topic": "T01_Alternator"}, {"cat": "FT", "q": "An alternator trips on differential protection while running at 75% load. What fault does this indicate?", "a": "Internal fault in the stator winding \u2014 turn-to-turn short, phase-to-earth, or phase-to-phase inside the machine", "opts": ["External short circuit on the busbar", "Internal fault in the stator winding \u2014 turn-to-turn short, phase-to-earth, or phase-to-phase inside the machine", "Reverse power \u2014 prime mover has stalled", "Earth fault on connected equipment"], "exp": "Differential relay ONLY operates for faults within the protected zone (between the CTs at each end of stator winding). External faults (busbar shorts, cable faults) would be seen equally by both CTs \u2192 no differential \u2192 relay doesn't operate. Differential trip \u2192 internal fault. Machine must be shut down, isolated, and inspected/meggered before return to service.", "id": "T01_NEW_074", "topic": "T01_Alternator"}, {"cat": "FT", "q": "What does it mean when an alternator 'loses excitation' while running in parallel?", "a": "Field current drops to zero \u2014 machine de-excites, loses synchronism, operates as induction generator absorbing reactive power", "opts": ["Governor fails and machine over-speeds", "Field current drops to zero \u2014 machine de-excites, loses synchronism, operates as induction generator absorbing reactive power", "Stator winding open circuits in all three phases", "Reverse power relay trips due to high load"], "exp": "Sequence: AVR or exciter fault \u2192 field current drops \u2192 rotor magnetism collapses \u2192 machine cannot maintain synchronism \u2192 it slips poles \u2192 now runs as induction generator (asynchronously). In this mode: absorbs reactive power from busbar \u2192 busbar voltage drops. Detectable: machine's power factor meter goes leading/capacitive, current drops then may fluctuate. Loss-of-excitation relay (or UV relay) should trip.", "id": "T01_NEW_075", "topic": "T01_Alternator"}, {"cat": "SR", "q": "What are the signs that an alternator brush is wearing too quickly?", "a": "Frequent brush replacement needed, excessive brush dust, sparking at slip ring, high brush temperature", "opts": ["Brush sparking only in UMS mode", "Frequent brush replacement needed, excessive brush dust, sparking at slip ring, high brush temperature", "Brush wears faster in tropical climates \u2014 normal", "Rapid wear indicates wrong field current \u2014 reduce excitation"], "exp": "Too rapid brush wear indicates: (1) Excessive brush pressure \u2014 increases friction wear. (2) Wrong brush grade \u2014 too soft wears fast. (3) Slip ring surface rough/eccentric \u2014 mechanical wear. (4) High humidity causing electrochemical corrosion. (5) Current density too high \u2014 use larger brush or multiple brushes. Investigate before fitting new brush \u2014 root cause must be resolved.", "id": "T01_NEW_076", "topic": "T01_Alternator"}, {"cat": "SR", "q": "How do you check brush pressure on a slip ring brush?", "a": "Use a spring balance gauge \u2014 hook under the brush holder spring, read force while brush is lifted slightly off ring", "opts": ["Press with thumb \u2014 should feel firm but not hard", "Use a spring balance gauge \u2014 hook under the brush holder spring, read force while brush is lifted slightly off ring", "Measure brush current with clamp meter \u2014 infer pressure", "Tap brush holder \u2014 if it bounces, pressure is too low"], "exp": "Spring balance method: (1) Machine running or stopped. (2) Hook spring balance under brush holder spring. (3) Lift until brush just separates from slip ring. (4) Read force at separation point. (5) Compare to spec (typically 150-200 g/cm\u00b2). Too low \u2192 adjust spring or replace. Too high \u2192 loosen spring. Log reading.", "id": "T01_NEW_077", "topic": "T01_Alternator"}, {"cat": "SR", "q": "After dressing slip ring pitting with emery cloth, how do you verify the repair was successful?", "a": "Check contact surface is smooth and bright; observe sparking is reduced/eliminated; monitor brush temperature for 30 min", "opts": ["Megger test the slip ring to earth", "Check contact surface is smooth and bright; observe sparking is reduced/eliminated; monitor brush temperature for 30 min", "Take the machine off-load and measure field resistance", "Install new brushes \u2014 old brushes become contaminated from pitting"], "exp": "Post-dressing checks: (1) Visual \u2014 slip ring surface should be smooth, bright (not glazed or rough). A thin film of brush 'patina' is acceptable. (2) Electrical \u2014 sparking at contact should stop. (3) Thermal \u2014 brush temperature at normal load should be within limits. (4) If pitting returns quickly \u2192 root cause not addressed (pressure, grade, contamination).", "id": "T01_NEW_078", "topic": "T01_Alternator"}, {"cat": "SR", "q": "What is 'electrical glazing' on a slip ring and what causes it?", "a": "A hard, shiny, poorly-conducting oxide/graphite film on the slip ring surface \u2014 caused by very low current density or wrong brush grade", "opts": ["Normal \u2014 glazing is the desired patina for good contact", "A hard, shiny, poorly-conducting oxide/graphite film on the slip ring surface \u2014 caused by very low current density or wrong brush grade", "Glazing is a sign of good lubrication", "Glazing occurs from excessive current density"], "exp": "Some graphite patina on slip rings is good \u2014 it reduces friction and improves contact. But excessive glazing (hard, dark, non-conducting film) blocks current \u2192 increased contact resistance \u2192 heating \u2192 more arcing \u2192 more pitting. Causes: insufficient load current density, wrong brush compound, dry conditions. Fix: lightly dress with fine emery cloth to expose clean copper.", "id": "T01_NEW_079", "topic": "T01_Alternator"}, {"cat": "EM", "q": "What is the difference between the emergency generator and the emergency battery system?", "a": "Emergency battery provides instant power for <30 min; emergency generator provides sustained power for 18/36 hours after up to 45s delay", "opts": ["They are the same system with different starting modes", "Emergency battery provides instant power for <30 min; emergency generator provides sustained power for 18/36 hours after up to 45s delay", "Emergency generator only supplies batteries \u2014 batteries supply loads", "Batteries are for radio only; generator is for propulsion"], "exp": "Emergency battery (transitional): supplies certain loads INSTANTLY and CONTINUOUSLY during the 45 seconds before DG starts \u2014 typically: UPS for navigation systems, battery-backed emergency lighting (shedding), EPIRB. Emergency generator: starts within 45 seconds and provides sustained supply for 18h (pax) or 36h (cargo). Both are required by SOLAS.", "id": "T01_NEW_080", "topic": "T01_Alternator"}, {"cat": "EM", "q": "The emergency generator fails to auto-start during a blackout. What manual procedure do you follow?", "a": "Go to emergency generator room, check fuel/oil, attempt local manual start, transfer loads manually to emergency switchboard", "opts": ["Wait for shore power \u2014 manual start is not permitted", "Go to emergency generator room, check fuel/oil, attempt local manual start, transfer loads manually to emergency switchboard", "Send distress signal \u2014 blackout is an emergency requiring rescue", "Use battery-only power indefinitely until auto-start problem resolved"], "exp": "Procedure: (1) Go to emergency generator space immediately. (2) Check fuel level, oil pressure. (3) Check battery/starting system. (4) Attempt local manual start. (5) If started manually: manually close emergency switchboard breakers in correct priority order. (6) Inform bridge and log. (7) Investigate auto-start failure (starting battery, auto-start relay, fuel solenoid). (8) Repair before next entry to any port.", "id": "T01_NEW_081", "topic": "T01_Alternator"}, {"cat": "EM", "q": "What are the minimum acceptable tests for the emergency generator per CLASS requirements?", "a": "Monthly: running test under load for minimum 1 hour; Annual: full blackout test verifying 45-second start", "opts": ["Weekly: visual check only; Annual: full start test", "Monthly: running test under load for minimum 1 hour; Annual: full blackout test verifying 45-second start", "Quarterly: start test; every 5 years: full blackout test", "Only when surveyor is onboard"], "exp": "Typical class requirements: (1) Monthly: start and run at load for minimum 1 hour \u2014 checks starting system, governor, AVR, and sustained running. (2) Annual (or at surveyor): full blackout test \u2014 trip main switchboard, verify auto-start within 45 seconds, verify essential loads fed. (3) Log all tests with date, duration, result. (4) Deficiencies must be repaired and retested.", "id": "T01_NEW_082", "topic": "T01_Alternator"}, {"cat": "BL", "q": "What is the full excitation current path in a brushless alternator from start to finish?", "a": "PMG AC \u2192 AVR rectifier \u2192 DC to exciter stator coil \u2192 exciter rotor cuts stator field \u2192 3-phase AC in exciter rotor \u2192 rotating diodes \u2192 DC field in main rotor \u2192 main rotor cuts stator conductors \u2192 3-phase AC output", "opts": ["Battery \u2192 Field winding \u2192 Stator \u2192 Output", "PMG AC \u2192 AVR rectifier \u2192 DC to exciter stator coil \u2192 exciter rotor cuts stator field \u2192 3-phase AC in exciter rotor \u2192 rotating diodes \u2192 DC field in main rotor \u2192 main rotor cuts stator conductors \u2192 3-phase AC output", "Shore supply \u2192 Transformer \u2192 Field \u2192 Output", "AVR \u2192 Rotating diodes \u2192 PMG \u2192 Main stator \u2192 Output"], "exp": "This is the complete chain \u2014 memorise it for oral exams. Key points: PMG is the start (stable, independent). AVR controls the DC fed to the exciter. The exciter works 'inside out' (stator is DC field, rotor is armature). Rotating diodes do the AC\u2192DC conversion on the shaft without brushes. Final output from main stator.", "id": "T01_NEW_083", "topic": "T01_Alternator"}, {"cat": "PR", "q": "What is the effect of a failed open-circuit reverse power relay on a generator coming off-line?", "a": "If prime mover fails and relay doesn't trip, generator motors (runs as induction motor), drawing heavy current from busbar, damaging engine/coupling", "opts": ["Generator automatically disconnects via overcurrent relay", "If prime mover fails and relay doesn't trip, generator motors (runs as induction motor), drawing heavy current from busbar, damaging engine/coupling", "No effect \u2014 other protections cover this", "Generator overspeeds if relay fails open"], "exp": "A failed (open-circuit) reverse power relay means it cannot trip. If prime mover stalls: busbar back-feeds the generator \u2192 induction motoring \u2192 heavy current \u2192 diesel engine driven backward against compression \u2192 severe mechanical shock to couplings, gearbox, engine components. The differential relay may eventually trip (if internal fault develops), but the overcurrent relay may also trip \u2014 depending on the level of motoring current.", "id": "T01_NEW_084", "topic": "T01_Alternator"}, {"cat": "AVR", "q": "An AVR has 'under-excitation limiter' (UEL) protection. When does it operate?", "a": "When field current drops too low \u2014 prevents operation in capacitive (leading PF) region which can cause loss of synchronism", "opts": ["When terminal voltage drops below 85% \u2014 same as UV relay", "When field current drops too low \u2014 prevents operation in capacitive (leading PF) region which can cause loss of synchronism", "When load exceeds 100% rated \u2014 reduces field current", "When temperature exceeds Class F limit"], "exp": "Under-excitation (low field current) \u2192 generator absorbs reactive power \u2192 operates at leading PF \u2192 stability limit approached \u2192 risk of pulling out of synchronism. UEL prevents the AVR from reducing field current below a minimum safe value. Particularly important for large generators near steady-state stability limits. Common in ship's HV alternators.", "id": "T01_NEW_085", "topic": "T01_Alternator"}, {"cat": "WP", "q": "Why do marine alternators use salient-pole rotors rather than cylindrical rotors (except on turbine ships)?", "a": "Salient-pole rotors are practical for low/medium speed prime movers (diesels) \u2014 many poles without high centrifugal stress; cylindrical needed for high-speed (turbines)", "opts": ["Salient poles are cheaper to manufacture", "Salient-pole rotors are practical for low/medium speed prime movers (diesels) \u2014 many poles without high centrifugal stress; cylindrical needed for high-speed (turbines)", "Cylindrical rotors cannot carry DC field windings", "Salient poles produce better waveform quality"], "exp": "Diesel-driven alternators run at 750-1500 RPM \u2014 need many poles (6-12) for 50/60 Hz. Salient poles (projecting poles with concentrated windings) are easy to manufacture in large numbers and the centrifugal force at 1500 RPM is manageable. Turbo-alternators run at 3000 RPM (50 Hz) or 3600 RPM (60 Hz) \u2014 only 2 poles, cylindrical rotor needed to withstand extreme centrifugal forces.", "id": "T01_NEW_086", "topic": "T01_Alternator"}, {"cat": "MT", "q": "What is the purpose of applying Class F varnish to stator windings during rewind?", "a": "Impregnates and consolidates the winding \u2014 improves insulation, thermal conductivity, moisture resistance, and mechanical strength", "opts": ["Reduces copper resistance for better conductivity", "Impregnates and consolidates the winding \u2014 improves insulation, thermal conductivity, moisture resistance, and mechanical strength", "Class F varnish is mandatory per MARPOL regulations", "Prevents rust on the copper conductors"], "exp": "Vacuum Pressure Impregnation (VPI) with Class F insulating varnish: (1) Fills all voids between conductors \u2192 consolidates winding \u2192 eliminates movement and vibration damage. (2) Improves thermal conductivity \u2192 heat flows better to stator core. (3) Waterproofs the winding \u2192 moisture resistance. (4) Class F rated to 155\u00b0C \u2192 matches Class F insulation. Properly varnished windings last decades.", "id": "T01_NEW_087", "topic": "T01_Alternator"}, {"cat": "FT", "q": "Three-phase voltage is 440V but single-phase measurements show R-N=254V, Y-N=254V, B-N=180V. What fault does this indicate?", "a": "B-phase has a partial winding fault \u2014 lower B-phase stator winding", "opts": ["Normal variation \u2014 phase-to-neutral voltages can differ", "B-phase has a partial winding fault \u2014 lower B-phase stator winding", "Earth fault on B phase equipment", "Governor hunting causing frequency variation on B phase"], "exp": "Balanced 3-phase: all phase-to-neutral voltages should be 440/\u221a3 = 254V. R=254, Y=254, B=180 \u2192 B-phase voltage low. This indicates reduced B-phase EMF, likely: (1) Partial turn-to-turn short in B-phase stator winding (effective turns reduced \u2192 EMF reduced). (2) Check: is B-phase terminal connection loose? (3) If winding fault confirmed \u2192 machine off-line for rewinding of B phase.", "id": "T01_NEW_088", "topic": "T01_Alternator"}, {"cat": "SY", "q": "After paralleling, the incoming generator immediately takes a heavy surge of current and the OCR nearly trips. What was done wrong?", "a": "ACB was closed with too large a speed/phase difference \u2014 incoming machine was too fast or at wrong phase angle", "opts": ["AVR was not set correctly before paralleling", "ACB was closed with too large a speed/phase difference \u2014 incoming machine was too fast or at wrong phase angle", "Load was too high on the busbar for paralleling", "Governor was in isochronous mode \u2014 should be droop mode"], "exp": "Closing ACB with significant phase or speed difference causes a large instantaneous voltage difference between the machines \u2192 large equalising current \u2192 surge. For 'slightly too fast': heavy load surge on incoming machine. For 'large phase angle': both machines see large differential voltage \u2192 can be hundreds of amps. Solution: ensure pointer is barely moving CW at 12 o'clock before closing.", "id": "T01_NEW_089", "topic": "T01_Alternator"}, {"cat": "LS", "q": "What is 'isochronous' governor mode and why can't two generators run in parallel in this mode?", "a": "Isochronous = maintains exactly constant speed regardless of load; two isochronous governors fight each other \u2192 no stable load sharing", "opts": ["Isochronous means governor controls frequency only \u2014 suitable for parallel operation", "Isochronous = maintains exactly constant speed regardless of load; two isochronous governors fight each other \u2192 no stable load sharing", "Isochronous mode is required for parallel operation", "Isochronous governors automatically equalise kW sharing"], "exp": "Isochronous governor: if any load change occurs, it immediately restores exact rated speed. Two such governors in parallel: if machine A takes slightly more load and slows 0.1 RPM, its governor brings it back to exactly 1500 RPM \u2014 but now it's faster than machine B \u2192 takes even more load \u2192 unstable. Droop governors avoid this: speed droops slightly as load increases \u2192 natural stable equilibrium point.", "id": "T01_NEW_090", "topic": "T01_Alternator"}, {"cat": "SOL", "q": "SOLAS requires generators to be protected against flooding. What is the practical minimum height above tank top for the main generator?", "a": "Above the bulkhead deck level \u2014 in practice, typically on the second or third platform above tank top", "opts": ["At tank top level is acceptable if flood detection is fitted", "Above the bulkhead deck level \u2014 in practice, typically on the second or third platform above tank top", "Any height above bilge level", "Must be above the waterline mark only"], "exp": "The bulkhead deck is the deck to which the ship's watertight bulkheads extend. SOLAS II-1/40 requires main power sources to be protected from flooding that might result from hull breach. In practice, this means generators are placed on elevated platforms \u2014 second platform or higher in engine room \u2014 well above the maximum expected flood waterline.", "id": "T01_NEW_091", "topic": "T01_Alternator"}]);
